    array("number" => 2001, "name" => "#53 - #94", "rating" => 8, "episodes" => array(
        array("id" => "s2001e1", "season" => 2001, "number" => 1, "name" => "The Legend has Begun! Head to the Grand Line", "airdate" => "10 Jan 2001", "runtime" => 25, "rating" => 9.2, "summary" => "Miraculously saved from death by an unnatural green gust and a lightning bolt to Buggy, the Straw Hats rush out of Loguetown, only for Zoro to be stopped by Tashigi and Luffy to be stopped by Captain Smoker.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734412.jpg"),
        array("id" => "s2001e2", "season" => 2001, "number" => 2, "name" => "Foreboding of a New Adventure! The Puzzling Girl, Apis", "airdate" => "17 Jan 2001", "runtime" => 25, "rating" => 8, "summary" => "On a stormy night a girl called Apis escapes from the Marines and arrives at Straw hat's ship, but the girl upon knowing that they are pirates begins to hide some of the reasons which she is being wanted by the Marines. As the Straw Hats escape from the Marin…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734419.jpg"),
        array("id" => "s2001e3", "season" => 2001, "number" => 3, "name" => "The Holy Beast! Apis' Secret and the Legendary Island", "airdate" => "24 Jan 2001", "runtime" => 25, "rating" => 7, "summary" => "The Calm Belt is revealed to have no winds or currents as well as being the home of many giant sea kings. Apis forms a plan with Luffy's help and escapes the sea kings by riding with one's sneeze. Later, the crew reaches Warship Island, where they listen to t…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734420.jpg"),
        array("id" => "s2001e4", "season" => 2001, "number" => 4, "name" => "Erik's Raid! Great Escape from Gunkan Island!", "airdate" => "31 Jan 2001", "runtime" => 25, "rating" => 7, "summary" => "Now that the crew is informed about the reasons for which Apis was followed, they hurry to escape the island so Ryuuji could be saved, but they meet with a foe that wants Ryuuji to himself. Zoro and Usopp bring the ship to a thin rock at the side while Nami a…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734421.jpg"),
        array("id" => "s2001e5", "season" => 2001, "number" => 5, "name" => "Lone Island in a Distant Sea! The Legendary Lost Island", "airdate" => "7 Feb 2001", "runtime" => 25, "rating" => 7.3, "summary" => "After arriving to what might seemed as the Lost Island the Straw hats where looking for, they find an old Temple with paintings that might indicate where the Lost Island really is, and also Eric who has been following them throughout the sea.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734422.jpg"),
        array("id" => "s2001e6", "season" => 2001, "number" => 6, "name" => "Duel in the Ruins! Strained Zoro vs. Erik", "airdate" => "21 Feb 2001", "runtime" => 25, "rating" => 7, "summary" => "Zoro is left fighting with Eric while Luffy and the gang run to the ship in order to get to Lost Island, but only find more problems.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734423.jpg"),
        array("id" => "s2001e7", "season" => 2001, "number" => 7, "name" => "Luffy, Completely Surrounded! Admiral Nelson's Secret Plan", "airdate" => "21 Feb 2001", "runtime" => 25, "rating" => 7, "summary" => "At last Admiral Nelson has seen through the ambitions of Eric, but takes it a little too personally and now the mystical dragon's life is in danger.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734424.jpg"),
        array("id" => "s2001e8", "season" => 2001, "number" => 8, "name" => "Those who Soar in the Open Skies! Revival of the 1000 Year Legend", "airdate" => "28 Feb 2001", "runtime" => 25, "rating" => 7, "summary" => "With his last breath, Ryuuji calls all his fellow dragons, and the Lost Island re-surfaced. Meanwhile Luffy takes out Admiral Nelson and his gang.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734425.jpg"),
        array("id" => "s2001e9", "season" => 2001, "number" => 9, "name" => "Angry Finale! Cross the Red Line!", "airdate" => "7 Mar 2001", "runtime" => 25, "rating" => 8.3, "summary" => "After leaving Warship Island the Going Merry is now towards the Grand Line, and the crew now returns to the Great Adventure.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734426.jpg"),
        array("id" => "s2001e10", "season" => 2001, "number" => 10, "name" => "The First Obstacle? Giant Whale Laboon Appears", "airdate" => "21 Mar 2001", "runtime" => 25, "rating" => 8.3, "summary" => "Upon entering the Grand Line, the ship is swallowed by a giant whale, inside of which they discover a strange place. In addition, they are not the only ones there.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734465.jpg"),
        array("id" => "s2001e11", "season" => 2001, "number" => 11, "name" => "A Man's Promise, Luffy and the Whale Vow to Meet Again", "airdate" => "21 Mar 2001", "runtime" => 25, "rating" => 8.3, "summary" => "After hearing the story of Laboon the whale, Luffy comes up with a clever solution to his problems. From Laboon's caretaker, Crocus, the crew learns more about the Grand Line and how to navigate through it, since compasses are useless there.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734466.jpg"),
        array("id" => "s2001e12", "season" => 2001, "number" => 12, "name" => "A Pirate-Loving Town? Arrival at Whiskey Peak", "airdate" => "15 Apr 2001", "runtime" => 25, "rating" => 8, "summary" => "Luffy and friends arrive at Whisky Peak, a town of pirate-lovers who hold them a feast.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734467.jpg"),
        array("id" => "s2001e13", "season" => 2001, "number" => 13, "name" => "Exploding Santouryu! Zoro vs. Baroque Works!", "airdate" => "15 Apr 2001", "runtime" => 25, "rating" => 8, "summary" => "Zoro battles a hundred members of Baroque Works, and discovers there is more to them than meets the eye.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734468.jpg"),
        array("id" => "s2001e14", "season" => 2001, "number" => 14, "name" => "A Serious Fight! Luffy vs. Zoro: The Unexpected Duel!", "airdate" => "22 Apr 2001", "runtime" => 25, "rating" => 7.3, "summary" => "Luffy, who does not realize the town is full of bounty hunters, engages in a battle with Zoro after he discovers that Zoro attacked the townsfolk, while Mr. 5 and Miss Valentine head for Princess Vivi.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734469.jpg"),
        array("id" => "s2001e15", "season" => 2001, "number" => 15, "name" => "Deliver Princess Vivi! Luffy Pirates Depart", "airdate" => "29 Apr 2001", "runtime" => 25, "rating" => 9, "summary" => "Luffy's crew manages to become targets of Crocodile, one of the Shichibukai, and decide to help Princess Vivi. They also meet Miss All-Sunday, the second strongest member of Baroque Works and partner of Crocodile.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734470.jpg"),
        array("id" => "s2001e16", "season" => 2001, "number" => 16, "name" => "Try Hard, Koby! Diary of Koby-Meppo's Marine Struggles", "airdate" => "13 May 2001", "runtime" => 25, "rating" => 7, "summary" => "As Luffy and his crew are sailing in the Grand Line, Koby and Helmeppo are stuck doing odd-jobs for the marines back in East Blue, and encounter Vice-Admiral Garp.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734471.jpg"),
        array("id" => "s2001e17", "season" => 2001, "number" => 17, "name" => "Koby-Meppo's Determination! Vice Admiral Garp's Fatherly Pride", "airdate" => "20 May 2001", "runtime" => 25, "rating" => 7, "summary" => "Vice Admiral Garp mentors Koby and Helmeppo to become marines.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734472.jpg"),
        array("id" => "s2001e18", "season" => 2001, "number" => 18, "name" => "Prehistoric Island! The Shadow Lurking in Little Garden!", "airdate" => "27 May 2001", "runtime" => 25, "rating" => 7.3, "summary" => "Luffy and friends land on Little Garden, a prehistoric island inhabited by dinosaurs and giants.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734473.jpg"),
        array("id" => "s2001e19", "season" => 2001, "number" => 19, "name" => "Humongous Battle! The Giants Dorry and Brogy!", "airdate" => "3 Jun 2001", "runtime" => 25, "rating" => 8, "summary" => "Nami and Usopp meet a giant named Brogy, while Luffy and Vivi encounter Brogy's rival, Dorry. The Straw Hats little suspect that Officer Agents of Baroque Works are on their tail.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734474.jpg"),
        array("id" => "s2001e20", "season" => 2001, "number" => 20, "name" => "Luffy's Anger! A Dirty Trick in a Sacred Battle", "airdate" => "17 Jun 2001", "runtime" => 25, "rating" => 8, "summary" => "Dorry, critically injured by exploding ale, blames the Straw Hats. Luffy is enraged that someone would pull such a cowardly trick to sabotage the giants' honorable duel.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734475.jpg"),
        array("id" => "s2001e21", "season" => 2001, "number" => 21, "name" => "Brogy Wails in Victory! Elbaf's Judgement", "airdate" => "24 Jun 2001", "runtime" => 25, "rating" => 8, "summary" => "Luffy tries in vain to convince the injured Dorry not to fight Brogy. The Officer Agents who sabotaged Dorry's ale further tamper with the giants' duel.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734476.jpg"),
        array("id" => "s2001e22", "season" => 2001, "number" => 22, "name" => "The Devil's Candle! Tears of Regret and Tears of Anger", "airdate" => "15 Jul 2001", "runtime" => 25, "rating" => 8.3, "summary" => "Having subdued the giants, Baroque Works makes their move. Mr. 3 introduces Zoro, Nami, Vivi, and Brogy to the slow torture of becoming living statues of wax.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734477.jpg"),
        array("id" => "s2001e23", "season" => 2001, "number" => 23, "name" => "Luffy Attacked by Magic! Colors Trap", "airdate" => "12 Aug 2001", "runtime" => 25, "rating" => 9, "summary" => "Luffy attempts to rescue his friends but only accelerates the deadly waxing process. To make matters worse, Miss Goldenweek interferes and reveals her own terrifying ability.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734478.jpg"),
        array("id" => "s2001e24", "season" => 2001, "number" => 24, "name" => "Critical Counterattack! Usopp's Quick Wit and Kaenboshi!", "airdate" => "19 Aug 2001", "runtime" => 25, "rating" => 8, "summary" => "Usopp frees Luffy from Miss Goldenweek's control. With Karoo's help, Usopp and Luffy rescue the others, who take on Mr. 5 and Miss Valentine. Luffy and Karoo pursue Mr. 3 and Miss Goldenweek into the forest.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734479.jpg"),
        array("id" => "s2001e25", "season" => 2001, "number" => 25, "name" => "Farewell to the Giants' Island! On to Alabasta", "airdate" => "19 Aug 2001", "runtime" => 25, "rating" => 8.3, "summary" => "After having a pleasant chat with Mr. 0 and encountering the \"Unluckies\", Sanji retrieves an Eternal Pose for Arabasta. The crew leaves Little Garden and sets sail for Arabasta.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734480.jpg"),
        array("id" => "s2001e26", "season" => 2001, "number" => 26, "name" => "Nami Is Sick? Beyond the Snow that Falls on the Ocean!", "airdate" => "26 Aug 2001", "runtime" => 25, "rating" => 8.3, "summary" => "Nami is sick, but the crew does not have a doctor to help her.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734481.jpg"),
        array("id" => "s2001e27", "season" => 2001, "number" => 27, "name" => "Ambush! The Bliking and Wapol the Tin-man", "airdate" => "2 Sep 2001", "runtime" => 25, "rating" => 7.7, "summary" => "While looking for a doctor, the crew meets the pirate Wapol, who attacks them, but only makes Luffy send him flying. Meanwhile Smoker manages to intercept the conversation between Mr. 0 and Sanji and plans to go to Arabasta. Back with the crew they arrive at…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734482.jpg"),
        array("id" => "s2001e28", "season" => 2001, "number" => 28, "name" => "A Doctorless Island? Adventure in the Country Without a Name!", "airdate" => "9 Sep 2001", "runtime" => 25, "rating" => 7.7, "summary" => "The Straw Hat crew manages to gain the trust of the people that attacked them, and are taken to the village, except for Zoro and Karoo, who guard the ship. Luffy and Sanji must take Nami to the island's sole doctor who lives on a mountain-top. Vivi and Usopp…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734483.jpg"),
        array("id" => "s2001e29", "season" => 2001, "number" => 29, "name" => "Ya Happy? The Doctor who is Called a Witch!", "airdate" => "16 Sep 2001", "runtime" => 25, "rating" => 7.7, "summary" => "While Sanji and Luffy fight off the wilderness, the islander's worst nightmare turns true, as Wapol returns to the island. The doctor is discovered to be on the other side of the island, and Usopp, Vivi and Dalton rush to find her. Dalton however returns as h…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734484.jpg"),
        array("id" => "s2001e30", "season" => 2001, "number" => 30, "name" => "Dalton's Resolve! Wapol's Forces Land", "airdate" => "7 Oct 2001", "runtime" => 25, "rating" => 7.7, "summary" => "Dalton faces Wapol, but only gets himself hit by arrows thrown by his former comrade Chess. An avalanche stops the battle, but injures Sanji. Luffy must carry both Nami and Sanji to the doctor, and begins his ascent.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734772.jpg"),
        array("id" => "s2001e31", "season" => 2001, "number" => 31, "name" => "Island that Lives in Snow! Ascend The Drum Rockies!", "airdate" => "7 Oct 2001", "runtime" => 25, "rating" => 8.3, "summary" => "The Lapahn help Luffy escape from Wapol, giving him enough time to climb to the castle where doctor Kureha lives. Vivi, Usopp and Zoro deal with the king's army in order to save Dalton. The recovering Nami meets a strange creature.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734773.jpg"),
        array("id" => "s2001e32", "season" => 2001, "number" => 32, "name" => "The Blue-Nosed Reindeer! Chopper's Secret", "airdate" => "21 Oct 2001", "runtime" => 25, "rating" => 8.7, "summary" => "Nami asks Chopper to join the crew, but he is not interested. Kureha tells Nami some of what was Chopper's background. After realizing the abilities that Chopper has, Luffy is eager to make him join the crew.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734774.jpg"),
        array("id" => "s2001e33", "season" => 2001, "number" => 33, "name" => "Dream of the Outcasts! The Quack Doctor Hiruluk", "airdate" => "28 Oct 2001", "runtime" => 25, "rating" => 10, "summary" => "Doctorine continues to tell how Chopper lived his life and how the quack doctor Hiriluk took care of him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734775.jpg"),
        array("id" => "s2001e34", "season" => 2001, "number" => 34, "name" => "Hiruluk's Cherry Blossoms and Inherited Will", "airdate" => "4 Nov 2001", "runtime" => 25, "rating" => 10, "summary" => "More of Chopper's past is revealed, including the fate of doctor Hiriluk and Wapol's cruelties as the king. Meanwhile, Wapol reaches the castle where the crew is residing.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734777.jpg"),
        array("id" => "s2001e35", "season" => 2001, "number" => 35, "name" => "VS. Wapol's Army Corps! The Abilities of the Baku Baku Fruit!", "airdate" => "11 Nov 2001", "runtime" => 25, "rating" => 7.7, "summary" => "Wapol is determined to bring down Hiriluk's flag, and to do that, he engages Sanji, Luffy and Chopper in a fight.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734779.jpg"),
        array("id" => "s2001e36", "season" => 2001, "number" => 36, "name" => "Devil's Fruit of the Zoan Family! Chopper's Seven-Level Transformation", "airdate" => "18 Nov 2001", "runtime" => 25, "rating" => 8.3, "summary" => "Chopper demonstrates the abilities of Rumble Balls when fighting Chessmarimo. Dalton is uncovered from the avalanche.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734780.jpg"),
        array("id" => "s2001e37", "season" => 2001, "number" => 37, "name" => "When the Kingdom's Rule is Over! The Flag of Conviction Lasts Forever", "airdate" => "25 Nov 2001", "runtime" => 25, "rating" => 8.3, "summary" => "After trying every trick in the castle, Wapol is finally hunted down by Luffy. The villagers along with Zoro, Vivi and Usopp start their ascent to the castle through a ropeway.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734782.jpg"),
        array("id" => "s2001e38", "season" => 2001, "number" => 38, "name" => "Hiruluk's Cherry Blossoms! Miracle of the Drum Rockies", "airdate" => "2 Dec 2001", "runtime" => 25, "rating" => 9.3, "summary" => "After finally been convinced to join the team, Chopper announces his intentions to Dr. Kureha, who does not take it too well; but after escaping from the castle, she has decided to give the whole Straw Hat crew a farewell gift.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734783.jpg"),
        array("id" => "s2001e39", "season" => 2001, "number" => 39, "name" => "Farewell, Drum Island! I'm Going Out to Sea!", "airdate" => "9 Dec 2001", "runtime" => 25, "rating" => 8.3, "summary" => "Chopper joins the Straw Hat crew as they continue their journey to Vivi's homeland.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734785.jpg"),
        array("id" => "s2001e40", "season" => 2001, "number" => 40, "name" => "The Hero of Alabasta and the Ballerina on Deck", "airdate" => "9 Dec 2001", "runtime" => 25, "rating" => 7.3, "summary" => "Crocodile appears to stop rampaging pirates. Luffy and his crew meet Mr. 2 Bon Kurei, who shows off his Devil Fruit power; Vivi sees a shocking sight.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734787.jpg"),
        array("id" => "s2001e41", "season" => 2001, "number" => 41, "name" => "Coming to the Desert Kingdom! The Rain-Calling Powder and the Rebel Army", "airdate" => "16 Dec 2001", "runtime" => 25, "rating" => 7.3, "summary" => "Luffy separates from the rest of the crew, right after arriving at Arabasta's port city of Nanohana. The crew dons disguises while Luffy learns of Dance Powder.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734788.jpg"),
        array("id" => "s2001e42", "season" => 2001, "number" => 42, "name" => "Reunion of the Powerful! His Name Is Fire Fist Ace", "airdate" => "23 Dec 2001", "runtime" => 25, "rating" => 9.7, "summary" => "While in Nanohana, the Straw Hats encounter Smoker and Tashigi. A powerful pirate named Portgas D. Ace appears, and is revealed to be Luffy's older brother.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734789.jpg"),
    )),
    array("number" => 2002, "name" => "#95 - #138", "rating" => 8.2, "episodes" => array(
        array("id" => "s2002e1", "season" => 2002, "number" => 1, "name" => "Ace and Luffy! Warm Memories and Brotherly Bonds", "airdate" => "6 Jan 2002", "runtime" => 25, "rating" => 8.7, "summary" => "Ace fights Smoker while the Straw Hats run for their ship. Luffy reunites with his brother, and together take down agents of Baroque Works.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734790.jpg"),
        array("id" => "s2002e2", "season" => 2002, "number" => 2, "name" => "The Green City, Erumalu and the Kung Fu Dugongs", "airdate" => "13 Jan 2002", "runtime" => 25, "rating" => 8, "summary" => "Ace decides to travel with the Straw Hats, as he is hunting for a man known as Blackbeard. The group arrives first at the 'Green City' of Erumalu only to find it abandoned to the desert. Vivi and Nami explain what Dance Powder is and what it has done to Araba…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734791.jpg"),
        array("id" => "s2002e3", "season" => 2002, "number" => 3, "name" => "Adventure in the Country of Sand! The Demons that Live in the Scorching Earth", "airdate" => "20 Jan 2002", "runtime" => 25, "rating" => 7, "summary" => "After leaving Erumalu, the Straw Hats plus Vivi & Ace continue through the desert, facing the many dangers of it.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734793.jpg"),
        array("id" => "s2002e4", "season" => 2002, "number" => 4, "name" => "Here Come the Desert Pirates! The Men who Live Free", "airdate" => "27 Jan 2002", "runtime" => 25, "rating" => 7, "summary" => "Nami and Vivi found themselves an easier way to travel in the desert and leave all men behind. While trying to catch up with them, Ace gets lost. Luffy and the rest of the gang find the Desert Pirates, and Vivi meets a figure from her past.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734795.jpg"),
        array("id" => "s2002e5", "season" => 2002, "number" => 5, "name" => "Spirit of the Fakes! Heart of the Rebel Army, Kamyu!", "airdate" => "3 Feb 2002", "runtime" => 25, "rating" => 6.7, "summary" => "After hearing that a small village has fake Rebel Army bodyguards that have been keeping peace, Vivi asks the men of the crew to test if they are worthy of staying.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734797.jpg"),
        array("id" => "s2002e6", "season" => 2002, "number" => 6, "name" => "Rebel Warrior Kohza! The Dream Sworn to Vivi!", "airdate" => "10 Feb 2002", "runtime" => 25, "rating" => 7.7, "summary" => "Still trekking through the Arabasta desert, the crew beats up a giant desert scorpion for lunch, while Vivi tells Nami about her past and her friendship with Koza.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734799.jpg"),
        array("id" => "s2002e7", "season" => 2002, "number" => 7, "name" => "Showdown in a Heat Haze! Ace vs. the Gallant Scorpion!", "airdate" => "17 Feb 2002", "runtime" => 25, "rating" => 7, "summary" => "Ace finds out that Blackbeard is not in Arabasta after all, and leaves the group to continue looking for him. He leaves Luffy a mysterious piece of paper, explaining that it 'will let them meet again.'", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734801.jpg"),
        array("id" => "s2002e8", "season" => 2002, "number" => 8, "name" => "Ruins and Lost Ones! Vivi, Comrades, and the Shape of a Country", "airdate" => "24 Feb 2002", "runtime" => 25, "rating" => 7, "summary" => "Zoro, Chopper and Luffy manage to get themselves lost and stumble across some huge underground ruins.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734802.jpg"),
        array("id" => "s2002e9", "season" => 2002, "number" => 9, "name" => "At Spiders Cafe: The Enemy Ringleaders Meet at 8 o'clock", "airdate" => "3 Mar 2002", "runtime" => 25, "rating" => 7.7, "summary" => "Baroque Works plan starts to take effect, and for that, the Number Agents gather to meet Mr. 0. Meanwhile, crew finds out that the Rebel Army has moved out of Yuba and headed to Katorea, and the rebel leader Koza is determined to attack.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734803.jpg"),
        array("id" => "s2002e10", "season" => 2002, "number" => 10, "name" => "Luffy vs. Vivi! A Tearful Vow for Comrades", "airdate" => "10 Mar 2002", "runtime" => 25, "rating" => 9, "summary" => "Vivi and Luffy disagree in how to stop the rebel army and Baroque Works, leading to a fight.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/426/1065572.jpg"),
        array("id" => "s2002e11", "season" => 2002, "number" => 11, "name" => "The Alabasta War Front! City of Dreams, Rainbase", "airdate" => "17 Mar 2002", "runtime" => 25, "rating" => 8.3, "summary" => "The crew travels to the city of Rainbase to take down Crocodile and Baroque Works, but run afoul of Smoker and Tashigi.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734807.jpg"),
        array("id" => "s2002e12", "season" => 2002, "number" => 12, "name" => "Trap in a Desperate Situation! Breaking Into Rain Dinners", "airdate" => "24 Mar 2002", "runtime" => 25, "rating" => 8.7, "summary" => "Most of the Straw Hats, along with Smoker, are trapped by Crocodile. Vivi reunites with the royal guardian Pell, but is captured by Miss All-Sunday. Crocodile reveals his invincible Devil Fruit power.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734808.jpg"),
        array("id" => "s2002e13", "season" => 2002, "number" => 13, "name" => "Operation Utopia Commences! The Wave of Rebellion Begins to Move", "airdate" => "14 Apr 2002", "runtime" => 25, "rating" => 8.7, "summary" => "Baroque Works' plan to take over Arabasta is set in motion. The king is kidnapped and framed for a crime, and the rebel army begins to move.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734810.jpg"),
        array("id" => "s2002e14", "season" => 2002, "number" => 14, "name" => "The Fearsome Bananawani and Mr. Prince", "airdate" => "21 Apr 2002", "runtime" => 25, "rating" => 8.7, "summary" => "Most of the Straw Hats are helplessly trapped, but Crocodile is contacted by \"Mr. Prince\".", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734811.jpg"),
        array("id" => "s2002e15", "season" => 2002, "number" => 15, "name" => "The Key to Turning the Tide and a Great Escape! Doru Doru Ball!", "airdate" => "28 Apr 2002", "runtime" => 25, "rating" => 9, "summary" => "Chopper distracts Crocodile while Sanji frees the rest of the crew, but find themselves trapped yet again. Smoker's view on Luffy changes a little.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734813.jpg"),
        array("id" => "s2002e16", "season" => 2002, "number" => 16, "name" => "Merciless Fight to the Death! Luffy vs. Crocodile", "airdate" => "5 May 2002", "runtime" => 25, "rating" => 10, "summary" => "After escaping from Rain Dinners, the Straw Hats and Vivi cross the desert to Alubarne, where the final battle will take place. Crocodile, however, manages to catch Luffy, beginning the first round of their battle.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734815.jpg"),
        array("id" => "s2002e17", "season" => 2002, "number" => 17, "name" => "The Miracle Sprint! Alabasta the Animal Land", "airdate" => "12 May 2002", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy is left for dead by Crocodile, but is helped by the mysteríous Miss All-Sunday. Meanwhile, the rest of the Straw Hats reach Alubarna after encountering the Spot-Billed Duck Squad and dangers of Arabasta's main river.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734816.jpg"),
        array("id" => "s2002e18", "season" => 2002, "number" => 18, "name" => "Rebel Army vs. Royal Army! The Battle will be in Alubarna!", "airdate" => "19 May 2002", "runtime" => 25, "rating" => 9.3, "summary" => "The revolution is on the verge of starting and the crew comes out with a plan that could stop it.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734817.jpg"),
        array("id" => "s2002e19", "season" => 2002, "number" => 19, "name" => "Alubarna Grieves! The Fierce Captain Karoo!", "airdate" => "2 Jun 2002", "runtime" => 25, "rating" => 7.3, "summary" => "Vivi's attempts to stop the rebel army go to waste, and she is attacked by Mr. 2 Bon Kurei, but manages to escape. Meanwhile, the battle of Usopp and Chopper vs. the Mr. 4 team begins.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734818.jpg"),
        array("id" => "s2002e20", "season" => 2002, "number" => 20, "name" => "Swear on Your Comrade's Dream! Battle at Molehill 4th Avenue", "airdate" => "9 Jun 2002", "runtime" => 25, "rating" => 7.7, "summary" => "Things look hopeless for Usopp & Chopper as they continue to suffer from every attack that the Mr.4 team makes. However, the tides may be beginning to turn as Usopp learns what it truly means to be a man.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/426/1065701.jpg"),
        array("id" => "s2002e21", "season" => 2002, "number" => 21, "name" => "Today's Grand Performance! Mane Mane Montage!", "airdate" => "16 Jun 2002", "runtime" => 25, "rating" => 7.7, "summary" => "Albeit severely beaten and bruised, Usopp and Chopper have finally defeated the Mr.4 team. However, Mr. 2 has figured out Sanji's weakness.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734821.jpg"),
        array("id" => "s2002e22", "season" => 2002, "number" => 22, "name" => "Transforming Into Nami! Bon Clay's Hard-Hitting Ballet Kenpo", "airdate" => "23 Jun 2002", "runtime" => 25, "rating" => 8, "summary" => "Though Mr. 2 discovers Sanji's weakness, Sanji still defeats his opponent after an evenly-matched fight. Meanwhile, before Vivi could give the word to blow up the palace, Crocodile appears.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734823.jpg"),
        array("id" => "s2002e23", "season" => 2002, "number" => 23, "name" => "Nami's Whirlwind Warning! Clima Tact Explosion", "airdate" => "30 Jun 2002", "runtime" => 25, "rating" => 8.3, "summary" => "Nami faces off against Miss Doublefinger and tries to figure out her new weapon that Usopp made, the Clima-Tact.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734824.jpg"),
        array("id" => "s2002e24", "season" => 2002, "number" => 24, "name" => "Secret of the Royal Family! The Ancient Weapon, Pluton", "airdate" => "14 Jul 2002", "runtime" => 25, "rating" => 8.7, "summary" => "While Crocodile reveals to Vivi about the ancient weapon Pluton, Nami attempts to defeat Miss Doublefinger with her most powerful attack: The Tornado Tempo.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734825.jpg"),
        array("id" => "s2002e25", "season" => 2002, "number" => 25, "name" => "Essence of a Mighty Sword! The Power to Cut Steel and the Breath of All Things", "airdate" => "21 Jul 2002", "runtime" => 25, "rating" => 9, "summary" => "While Miss. Doublefinger's fight with Nami was challenging, Zoro is having an even more difficult time fighting Mr.1: A man who can change his entire body into steel - something that Zoro cannot cut. As Zoro nears death, he must discover the secret to \"the br…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734827.jpg"),
        array("id" => "s2002e26", "season" => 2002, "number" => 26, "name" => "The Battle is Over! Kohza Flies the White Flag", "airdate" => "4 Aug 2002", "runtime" => 25, "rating" => 8.3, "summary" => "When Vivi reveals Crocodile's plan to Koza, he attempts to stop the fighting, but is shot. Crocodile reveals that he has set up a massive bomb in the city.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734828.jpg"),
        array("id" => "s2002e27", "season" => 2002, "number" => 27, "name" => "Vivi's Voice Goes Unheard! A Hero Descends!", "airdate" => "11 Aug 2002", "runtime" => 25, "rating" => 8.7, "summary" => "As Koza tries to stop the Rebel Army, both sides are once more fighting due to the intervention of Baroque Works. Vivi is thrown to her certain death when Luffy saves her and challenges Crocodile to a second round.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734830.jpg"),
        array("id" => "s2002e28", "season" => 2002, "number" => 28, "name" => "Sand Crocodile and Water Luffy! Death Match: Round 2", "airdate" => "18 Aug 2002", "runtime" => 25, "rating" => 9, "summary" => "Luffy fights Crocodile with more success this time by using water, but still loses this round. Meanwhile, the other Straw Hats hurry to locate the bomb before it goes off. Nico Robin forces the king to take her to the tomb where the Pluton Poneglyph is hidden.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734832.jpg"),
        array("id" => "s2002e29", "season" => 2002, "number" => 29, "name" => "Smells Like Croc! Run to the Tomb of the Royal Family, Luffy!", "airdate" => "25 Aug 2002", "runtime" => 25, "rating" => 9, "summary" => "Crocodile joins Robin in the tomb, and orders her to translate the Poneglyph. Robin tells him that Pluton was not mentioned and that it was only about history, but Crocodile figures out that she was lying and stabs her in response. When Luffy recovers from th…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734833.jpg"),
        array("id" => "s2002e30", "season" => 2002, "number" => 30, "name" => "The Nightmare Draws Near! Secret Base of the Sand Sand Clan", "airdate" => "1 Sep 2002", "runtime" => 25, "rating" => 9, "summary" => "Luffy fights with Crocodile by using blood on his fists. Meanwhile Vivi finds the bomb, and calls the Straw Hats together.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734835.jpg"),
        array("id" => "s2002e31", "season" => 2002, "number" => 31, "name" => "Magnificent Wings! My Name is Pell, Guardian Spirit of the Kingdom", "airdate" => "8 Sep 2002", "runtime" => 25, "rating" => 10, "summary" => "Vivi finds the bomb inside of the clock tower, but the Mr. 7 pair of Baroque Works are there to protect it. Vivi defeats them, but she realizes the bomb cannot be stopped so easily. It has a timer, and right before it blows up, Pell shows up and takes it into…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734836.jpg"),
        array("id" => "s2002e32", "season" => 2002, "number" => 32, "name" => "I Will Surpass You! Rain Falls on Alabasta!", "airdate" => "15 Sep 2002", "runtime" => 25, "rating" => 9.3, "summary" => "Luffy defeats Crocodile by punching him through solid bedrock. When Crocodile falls, the rain-drops calm the soldiers.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734838.jpg"),
        array("id" => "s2002e33", "season" => 2002, "number" => 33, "name" => "A Farewell to Arms! Pirates and a Little Justice", "airdate" => "6 Oct 2002", "runtime" => 25, "rating" => 8.3, "summary" => "Now that the battle has ended, the outcome is tallied. Igaram appears with proof of Cobra's innocence, as well as Koza telling everything. Tashigi and Smoker both are rewarded for taking on Crocodile, but neither one of them believes that is right, considerin…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734839.jpg"),
        array("id" => "s2002e34", "season" => 2002, "number" => 34, "name" => "The Pirates' Banquet and Operation Escape Alabasta!", "airdate" => "6 Oct 2002", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy is rescued from the collapsed tomb where he fought Crocodile and brought into Cobra's palace to rest. When he awakens, a magnificent banquet is thrown for the pirates, then, the Straw Hats are invited to enjoy the hot spring steam room inside the palace.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734841.jpg"),
        array("id" => "s2002e35", "season" => 2002, "number" => 35, "name" => "Everything Began that Day! Vivi Tells of her Adventures!", "airdate" => "20 Oct 2002", "runtime" => 25, "rating" => 10, "summary" => "It's the day for Vivi's speech and her decision whether or not to continue to be with the Straw Hats. Meanwhile, Bon Kurei and his crew attempt to protect the Straw Hats from Hina.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734842.jpg"),
        array("id" => "s2002e36", "season" => 2002, "number" => 36, "name" => "Beware her Scent! The Seventh One is Nico Robin!", "airdate" => "27 Oct 2002", "runtime" => 25, "rating" => 9.4, "summary" => "The Marines fail again to catch the Straw Hats. After escaping from Marines, Nico Robin (Ms. All Sunday) appears from inside of Straw Hats ship. She manages to persuade the crew to let her join. Pell is seen at the end standing over his own grave.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734844.jpg"),
        array("id" => "s2002e37", "season" => 2002, "number" => 37, "name" => "The First Patient! Anecdote of the Rumble Ball", "airdate" => "3 Nov 2002", "runtime" => 25, "rating" => 9, "summary" => "After their adventures in Arabasta, the crew come upon another deserted island and split up tasks amongst themselves. Chopper is left in charge of guarding the ship, and he reminisces about the day he first made the rumble ball and his first patient, Dr. Kure…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734845.jpg"),
        array("id" => "s2002e38", "season" => 2002, "number" => 38, "name" => "The Navigator's Mutiny! For an Unwavering Dream!", "airdate" => "10 Nov 2002", "runtime" => 25, "rating" => 8, "summary" => "A weird salesman is fished out of the water and onto the Going Merry, and Nami buys a ton of \"1000 year paper\" from him to draw her sea maps. However, that's not going to be easy with the rest of the crew goofing off as usual.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734846.jpg"),
        array("id" => "s2002e39", "season" => 2002, "number" => 39, "name" => "Inherited Recipe! Sanji the Curry Expert", "airdate" => "17 Nov 2002", "runtime" => 25, "rating" => 7, "summary" => "The Going Merry runs into several Marine ships in some fog, and the Straw Hats meet a trainee Marine chef named Tajiyo. Sanji helps him out of a bit of cooking trouble.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734847.jpg"),
        array("id" => "s2002e40", "season" => 2002, "number" => 40, "name" => "I'll Make it Bloom! Manly Usopp's Eight-Shaku Ball", "airdate" => "24 Nov 2002", "runtime" => 25, "rating" => 6.5, "summary" => "The crew stops on an island that's having its annual fireworks festival; Usopp meets a young fireworks-maker named Kodama and helps her achieve her dream.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734848.jpg"),
        array("id" => "s2002e41", "season" => 2002, "number" => 41, "name" => "Infamous Pirate Hunter! The Wandering Swordsman, Zoro", "airdate" => "30 Nov 2002", "runtime" => 25, "rating" => 7.5, "summary" => "Zoro has a flashback about the time when he first met Johnny and Yosaku, and faced off against Bandits and, Dick.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/293/734850.jpg"),
        array("id" => "s2002e42", "season" => 2002, "number" => 42, "name" => "Zenny Lives on Goat Island and There's a Pirate Ship on his Mountain!", "airdate" => "8 Dec 2002", "runtime" => 25, "rating" => 7, "summary" => "After escaping from several Marine ships, the Straw Hats land on an uncharted island and meet an old man named Zenny. Chopper finds out that, because of his bad heart, Zenny probably only has three days to live.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735041.jpg"),
        array("id" => "s2002e43", "season" => 2002, "number" => 43, "name" => "How's That for Profit? Money Lender Zenny's Ambition!", "airdate" => "15 Dec 2002", "runtime" => 25, "rating" => 7.7, "summary" => "The Straw Hats help Zenny out, hoping to make his last days good ones; they learn about Zenny's past as a money lender, and his dream of becoming a pirate. But Zoro realizes that Zenny has outlived Chopper's predictions and so the straw hats decide that, afte…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735042.jpg"),
        array("id" => "s2002e44", "season" => 2002, "number" => 44, "name" => "Where the Island's Treasure Lies! Zenny Pirates Full Charge!", "airdate" => "22 Dec 2002", "runtime" => 25, "rating" => 7.3, "summary" => "Zenny decides to follow his dream and become a pirate, despite his age. He helps the Straw Hats out of trouble with the Marines, and then they part ways.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735044.jpg"),
    )),
    array("number" => 2003, "name" => "#139 - #175", "rating" => 8, "episodes" => array(
        array("id" => "s2003e1", "season" => 2003, "number" => 1, "name" => "Legend of the Rainbow Mist! Ruluka Island and the Old Man Henzo", "airdate" => "5 Jan 2003", "runtime" => 25, "rating" => 6, "summary" => "On Ruluka Island, some of the Straw Hats make enemies of the Mayor and his men, who have placed high taxes on everything. Robin, Usopp, and Luffy meet Professor Henzo, who's doing research on the island's rainbow mist. When some of the mist shows up, Henzo bo…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735045.jpg"),
        array("id" => "s2003e2", "season" => 2003, "number" => 2, "name" => "Inhabitants of Neverland! The Pumpkin Pirates!", "airdate" => "12 Jan 2003", "runtime" => 25, "rating" => 6, "summary" => "The inside of the Rainbow Mist full of wrecked ships and treasure, and is guarded by five kids. The kids are actually friends of Henzo's that got lost in the mist over 50 years ago.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735046.jpg"),
        array("id" => "s2003e3", "season" => 2003, "number" => 3, "name" => "A Longing for Home! The Inescapable Pirate Graveyard!", "airdate" => "19 Jan 2003", "runtime" => 25, "rating" => 6, "summary" => "Henzo, his friends, and the others try to find a way out of the ship graveyard. Meanwhile, the Mayor and his men let the information about the Rainbow Mist slip to the remaining Straw Hats still on Ruluka.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735047.jpg"),
        array("id" => "s2003e4", "season" => 2003, "number" => 4, "name" => "Frantic Struggle! Whetton's Plans and the Rainbow Tower", "airdate" => "26 Jan 2003", "runtime" => 25, "rating" => 6, "summary" => "Luffy accidentally propels himself and Rapanui to the end of the mist. Nami appears in the ship graveyard with a rowboat full of treasure and a string connected to the real world, which are both stolen by Wetton's subordinate. The Mayor uses the Rainbow Tower…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735048.jpg"),
        array("id" => "s2003e5", "season" => 2003, "number" => 5, "name" => "And Then the Legend Begins! To the End of the Rainbow", "airdate" => "2 Feb 2003", "runtime" => 25, "rating" => 6.3, "summary" => "The Going Merry escapes from the Rainbow Mist, getting badly damaged on the way. The Mayor gets arrested by a bunch of powerful marines that turn out to be older versions of Henzo's friends, who were thrown 50 years into the past by the Rainbow Mist's collaps…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735049.jpg"),
        array("id" => "s2003e6", "season" => 2003, "number" => 6, "name" => "The Log is Taken! Salvage King, Masira!", "airdate" => "9 Feb 2003", "runtime" => 25, "rating" => 7.3, "summary" => "Nami's log pose begins to point to the sky, and the crew finds a map of an island named 'Skypiea' on a 200-year-old ship. They compete with the monkey-like Masira's salvage crew while they search for more clues on how to get there.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735050.jpg"),
        array("id" => "s2003e7", "season" => 2003, "number" => 7, "name" => "Monsters Appear! Don't Touch the Whitebeard Pirates", "airdate" => "16 Feb 2003", "runtime" => 25, "rating" => 8, "summary" => "The Straw Hats decide to go to Jaya island to look for information on Skypeia. Meanwhile, Ace suddenly shows up on Buggy's ship; Buggy does not let any of his men attack Ace, fearing Whitebeard's retribution.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735051.jpg"),
        array("id" => "s2003e8", "season" => 2003, "number" => 8, "name" => "Stop Dreaming! The City of Ridicule, Mock Town!", "airdate" => "23 Feb 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Jaya's main town is full of famous pirates that are constantly brawling with each other. Luffy and Zoro have a run-in with a pirate known as 'Bellamy the Hyena,' who ridicules their dreams and beats them up.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735052.jpg"),
        array("id" => "s2003e9", "season" => 2003, "number" => 9, "name" => "A Pirate's Height! The Man who Talks of Dreams and the King of Underwater Exploration", "airdate" => "9 Mar 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy, Zoro and Nami meet the man who is later revealed to be Blackbeard. They leave Mock Town, and get into a fight with Masira's brother Shoujou, another salvage monkey.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735053.jpg"),
        array("id" => "s2003e10", "season" => 2003, "number" => 10, "name" => "The Legendary Family! 'Liar Norland'", "airdate" => "16 Mar 2003", "runtime" => 25, "rating" => 8.3, "summary" => "The Straw Hats meet with Mont Blanc Cricket on another part of Jaya; Cricket is a descendant of Montblanc Noland, an infamous \"liar\" who told of a gold city on Jaya, and Cricket was outcast for looking for artifacts of the gold city. He may be the only person…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/427/1067684.jpg"),
        array("id" => "s2003e11", "season" => 2003, "number" => 11, "name" => "Hard Turn to the Clouds! Find the Southbird!", "airdate" => "23 Mar 2003", "runtime" => 25, "rating" => 8, "summary" => "Cricket explains how the Straw Hats can ride a dangerous vertical current called the Knock-Up Stream to get to Skypeia. However, they first have to catch a southbird to point them toward the point where the stream will erupt from the ocean.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735055.jpg"),
        array("id" => "s2003e12", "season" => 2003, "number" => 12, "name" => "Dreams Don't Come True!? Bellamy vs. The Saruyama Alliance", "airdate" => "13 Apr 2003", "runtime" => 25, "rating" => 9, "summary" => "While the Straw Hats are looking for a Southbird, Bellamy and his crew attack Cricket's house, and steal the gold artifacts he'd collected over the years from his salvage work. When the Straw Hats return and see what happened, Luffy decides to take a side tri…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735056.jpg"),
        array("id" => "s2003e13", "season" => 2003, "number" => 13, "name" => "The 100 Million Man! The World's Greatest Authority and the Pirate Blackbeard", "airdate" => "20 Apr 2003", "runtime" => 25, "rating" => 10, "summary" => "Luffy takes out Bellamy with a single punch. Meanwhile, the world government heads are concerned over Whitebeard, Shanks, and Luffy. The marines try to decide who will replace Crocodile as a Shichibukai - one of Blackbeard's crew shows up uninvited and nomina…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735057.jpg"),
        array("id" => "s2003e14", "season" => 2003, "number" => 14, "name" => "Sail into the Sky! Ride the Knock-Up Stream", "airdate" => "27 Apr 2003", "runtime" => 25, "rating" => 10, "summary" => "The Going Merry is refitted by Masira and Shoujou to be more flight capable, and the Straw Hats catch a ride on the Knock-Up Stream for Skypeia.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735058.jpg"),
        array("id" => "s2003e15", "season" => 2003, "number" => 15, "name" => "This is the Sea of the Sky! The Knight of the Sky and Heaven's Gate", "airdate" => "4 May 2003", "runtime" => 25, "rating" => 8.3, "summary" => "The Straw Hats arrive in an ocean above the clouds. Usopp almost falls out of the Going Merry but is saved at the last minute. The crew is also attacked by a mysterious looking warrior, but is saved by the Knight of the Sky. Finally, they arrive at the border…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735059.jpg"),
        array("id" => "s2003e16", "season" => 2003, "number" => 16, "name" => "Godland Skypiea! The Angels Of the Cloud Beach", "airdate" => "11 May 2003", "runtime" => 25, "rating" => 7.7, "summary" => "As the crew arrives in Skypiea, they are greeted by Conis and her pet Su. Both she and her father start explaining how the life in Skypiea is and how the different Dials work.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735060.jpg"),
        array("id" => "s2003e17", "season" => 2003, "number" => 17, "name" => "Forbidden Sacred Ground! The Island Where God Resides and Heaven's Judgement!", "airdate" => "18 May 2003", "runtime" => 25, "rating" => 8, "summary" => "Nami finds out what should happen to anyone who enters the forest. Meanwhile, the rest of the gang are waiting for the wind to change but are rudely assaulted by Skypiea's police who are going to carry out Heaven's Judgement.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735061.jpg"),
        array("id" => "s2003e18", "season" => 2003, "number" => 18, "name" => "Already Criminals?! Skypiea's Upholder of the Law!", "airdate" => "25 May 2003", "runtime" => 25, "rating" => 8, "summary" => "The Straw Hats have some problems with the local justice enforcer force called \"The White Berets.\"", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735062.jpg"),
        array("id" => "s2003e19", "season" => 2003, "number" => 19, "name" => "Is Escape Possible?!? God's Challenge is Set in Motion", "airdate" => "15 Jun 2003", "runtime" => 25, "rating" => 8, "summary" => "While trying to escape from Sky Island, Robin, Chopper, Nami and Zoro are held hostages by God Enel.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735063.jpg"),
        array("id" => "s2003e20", "season" => 2003, "number" => 20, "name" => "Trap on Lovely Street! Almighty God Enel", "airdate" => "22 Jun 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Conis leads Luffy, Usopp, and Sanji to a boat to get to Upper Yard, but she tells them it is a trap and almost gets hit by \"Heaven's Judgment\".", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735064.jpg"),
        array("id" => "s2003e21", "season" => 2003, "number" => 21, "name" => "Go Forth, Little Crow! To the Sacrificial Altar", "airdate" => "6 Jul 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy, Usopp and Sanji finally enter Upper Yard, only to find out that the whole road is trapped heavily, but at last they arrive at the Ordeal Gates. Meanwhile Robin, Zoro, and Nami go out to explore Upper Yard while Chopper stays behind to guard the ship.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735065.jpg"),
        array("id" => "s2003e22", "season" => 2003, "number" => 22, "name" => "10 Percent Survival Rate! Satori, the Mantra Master!", "airdate" => "13 Jul 2003", "runtime" => 25, "rating" => 7.7, "summary" => "Luffy, Sanji, and Usopp enter the Ordeal of Balls gate and encounter the Priest Satori.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735066.jpg"),
        array("id" => "s2003e23", "season" => 2003, "number" => 23, "name" => "Peril of the Ordeal of Balls! Fight to the Death in the Lost Forest", "airdate" => "20 Jul 2003", "runtime" => 25, "rating" => 7.3, "summary" => "Usopp, Sanji and Luffy fight Satori, but the power of Mantra seems to be too strong.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735067.jpg"),
        array("id" => "s2003e24", "season" => 2003, "number" => 24, "name" => "Chopper's in Danger! Former God vs. Shinto priest Shura", "airdate" => "3 Aug 2003", "runtime" => 25, "rating" => 8, "summary" => "Chopper, threatened by priest Shura, blows the whistle for Gan Fall to come, but before he can arrive, Priest Shura assaults Chopper and begins destroying the Going Merry.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735068.jpg"),
        array("id" => "s2003e25", "season" => 2003, "number" => 25, "name" => "Ever Mysterious! Ordeal of String and Ordeal of Love!?", "airdate" => "10 Aug 2003", "runtime" => 25, "rating" => 7.7, "summary" => "Gan Fall cannot handle Shura and lost the battle. Meanwhile, Satori is finally defeated by Luffy and Sanji.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735069.jpg"),
        array("id" => "s2003e26", "season" => 2003, "number" => 26, "name" => "Light the Fire of Shandora! Wyper the Warrior", "airdate" => "17 Aug 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Chopper is saved by a bunch of giant Southbirds, who tell him that Gan Fall was actually God. Nami, Zoro and Robin discover the reason why Upper Yard is a soil island: It was once part of Jaya, and this is the part that Liar Noland saw. Meanwhile the Shandia…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735070.jpg"),
        array("id" => "s2003e27", "season" => 2003, "number" => 27, "name" => "Floating Land of Gold, Jaya! To God's Shrine!", "airdate" => "24 Aug 2003", "runtime" => 25, "rating" => 8.7, "summary" => "The Shandia attack on Upper Yard has started. The crew is finally reunited, and everyone speaks up about what has happened. Chopper takes care of Gan Fall, and the pirates plan to steal the gold on the island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735071.jpg"),
        array("id" => "s2003e28", "season" => 2003, "number" => 28, "name" => "Eve of Gold Festival! Feelings Toward 'Vearth'!", "airdate" => "7 Sep 2003", "runtime" => 25, "rating" => 8.7, "summary" => "After befriending a wolf pack, Gan Fall tells the crew a little more about the history of Upper Yard.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735072.jpg"),
        array("id" => "s2003e29", "season" => 2003, "number" => 29, "name" => "God Enel Appears! Aubade to the Survivors", "airdate" => "21 Sep 2003", "runtime" => 25, "rating" => 9, "summary" => "Enel takes away the limitations of the priests. Also, Usopp witnesses a mysterious person fixing the ship; the next day Merry is found to be back to her original form. After getting her off the altar, the pirates plan out their course of action.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735073.jpg"),
        array("id" => "s2003e30", "season" => 2003, "number" => 30, "name" => "The Python Strikes! The Survival Game Begins", "airdate" => "12 Oct 2003", "runtime" => 25, "rating" => 7.7, "summary" => "A giant python makes Luffy, Robin, Chopper and Zoro split while going to the ruins at the south.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735074.jpg"),
        array("id" => "s2003e31", "season" => 2003, "number" => 31, "name" => "The Life-Threatening Reject! War Demon Wiper's Resolve", "airdate" => "19 Oct 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Wyper takes out Shura and tells his goal to the Shandia, and Enel speaks up about how many people will be alive by the end of his plan.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735075.jpg"),
        array("id" => "s2003e32", "season" => 2003, "number" => 32, "name" => "Fierce Sky Battle! Pirate Zoro vs. Fighter Braham", "airdate" => "19 Oct 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Zoro fights the Shandia warrior Braham, and defeats him with Ittoryu (one sword style) 36 Pound Cannon technique.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735076.jpg"),
        array("id" => "s2003e33", "season" => 2003, "number" => 33, "name" => "The Roaring Burn Bazooka! Luffy vs. War Demon Wyper!", "airdate" => "26 Oct 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy fights Wyper, but after some time, he falls into some underground ruins. Meanwhile, Enel appears on the Going Merry and after telling that his true goal was the City of Gold, he takes out both Usopp and Sanji; then he vanishes and leaves Satori's brothe…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735077.jpg"),
        array("id" => "s2003e34", "season" => 2003, "number" => 34, "name" => "Ordeal of Swamp! Pirate Chopper vs Gedatsu!!", "airdate" => "2 Nov 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Chopper is attacked by Gedatsu, who turns out to be a complete moron, and eventually defeats him, sending him plummeting to the Blue Sea. Conis and Pagaya help Aisa, and head to Upper Yard.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735078.jpg"),
        array("id" => "s2003e35", "season" => 2003, "number" => 35, "name" => "The Invincible Ability! Enel's True Nature Revealed", "airdate" => "9 Nov 2003", "runtime" => 25, "rating" => 8.3, "summary" => "Enel defeats several members of the Shandia Tribe. Meanwhile, Gan Fall and Nami start and finish their fight with Kotori and Hotori. Hotori is defeated by Nami while Kotori is defeated by Gan Fall.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735079.jpg"),
        array("id" => "s2003e36", "season" => 2003, "number" => 36, "name" => "The Vanished City! The Magnificent Ruins of Shandora!!", "airdate" => "16 Nov 2003", "runtime" => 25, "rating" => 8.7, "summary" => "While Robin is looking at some ruins she found, Yama, The Chief Enforcer, attacks her. Yama is easily defeated by Robin. Later, she discovers the legendary city, Shandora.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735081.jpg"),
        array("id" => "s2003e37", "season" => 2003, "number" => 37, "name" => "Chance of Survival: 0%!! Pirate Chopper vs. Shinto Priest Ohm", "airdate" => "21 Dec 2003", "runtime" => 25, "rating" => 8, "summary" => "Priest Ohm appears and starts fighting everyone.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735082.jpg"),
    )),
    array("number" => 2004, "name" => "#176 - #214", "rating" => 8.4, "episodes" => array(
        array("id" => "s2004e1", "season" => 2004, "number" => 1, "name" => "Climb Giant Jack! Deadly Combat in the Upper Ruins", "airdate" => "4 Jan 2004", "runtime" => 25, "rating" => 8, "summary" => "At the Upper Ruins, the fight between Ohm, Zoro, Gan Fall and Wyper begins. When Nami appears, she is swallowed by the giant python, along with Gan Fall and Aisa.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735083.jpg"),
        array("id" => "s2004e2", "season" => 2004, "number" => 2, "name" => "Ultimate Test of the Ordeal of Iron! The White-Barbed Death Match!!", "airdate" => "18 Jan 2004", "runtime" => 25, "rating" => 8.3, "summary" => "Ohm makes matters worse, creating a barbed wire cage around the area. Laki is knocked out by Enel, and Nami, Aisa, and Gan Fall find out why the python was rampaging so much.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735084.jpg"),
        array("id" => "s2004e3", "season" => 2004, "number" => 3, "name" => "Gushing Blade Attack! Pirate Zoro vs Shinto Priest Ohm!!", "airdate" => "25 Jan 2004", "runtime" => 25, "rating" => 8.7, "summary" => "Zoro finally defeats Priest Ohm with his 108 Pound Cannon technique. Meanwhile Pagaya and Conis hear the terrible truth about the goal of Enel: to eradicate every person in the sky.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735085.jpg"),
        array("id" => "s2004e4", "season" => 2004, "number" => 4, "name" => "The Upper Ruins Crumble! The Quintet Finale!!", "airdate" => "1 Feb 2004", "runtime" => 25, "rating" => 8.7, "summary" => "Enel appears only to reduce the group as close to his prediction as he can.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/427/1068270.jpg"),
        array("id" => "s2004e5", "season" => 2004, "number" => 5, "name" => "Battle in the Ancient Ruins! God Enel's Desire!!", "airdate" => "8 Feb 2004", "runtime" => 25, "rating" => 9, "summary" => "Enel counterattacks Gan Fall and lands a finishing hit. He then knocks out Robin as she tries to manipulate him. Zoro impresses Enel with his power but is easily beaten, while trying to make him pay for what he did to Robin; but it takes Wyper with a secret w…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735087.jpg"),
        array("id" => "s2004e6", "season" => 2004, "number" => 6, "name" => "Ambitions of Fairy Vearth - The Ark, Maxim!!", "airdate" => "15 Feb 2004", "runtime" => 25, "rating" => 8.3, "summary" => "Enel defeats Zoro and Wyper. Upon seeing this, Nami follows him to a cave where his ark, Maxim, is. Luffy finally gets out of the snake, along with Aisa, only to find out the outcome of the fight against Enel. When Aisa tells him that she knows where he is, h…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735089.jpg"),
        array("id" => "s2004e7", "season" => 2004, "number" => 7, "name" => "Finally Clashing! Pirate Luffy vs God Enel!!", "airdate" => "22 Feb 2004", "runtime" => 25, "rating" => 8.7, "summary" => "Luffy and Enel start fighting. Conis tells the dangers of staying in Sky Island to the other Skypieans.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735090.jpg"),
        array("id" => "s2004e8", "season" => 2004, "number" => 8, "name" => "Maxim Rises! The Start of Deathpiea!!", "airdate" => "29 Feb 2004", "runtime" => 25, "rating" => 9.3, "summary" => "The fight between Enel and Luffy continues with Enel starting a machine that would bring the death of Skypiea: Deathpiea.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735091.jpg"),
        array("id" => "s2004e9", "season" => 2004, "number" => 9, "name" => "Luffy's Fall! God's Judgement and Nami's Desire!!", "airdate" => "7 Mar 2004", "runtime" => 25, "rating" => 9, "summary" => "Luffy falls from the ark. Nami starts fighting Enel while Sanji and Usopp try to rescue her.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735092.jpg"),
        array("id" => "s2004e10", "season" => 2004, "number" => 10, "name" => "Two People Awaken! A Rescue in Front of Burning Love!!", "airdate" => "14 Mar 2004", "runtime" => 25, "rating" => 9, "summary" => "Usopp and Sanji split up to rescue Nami, but the first one to get on deck is Usopp.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735093.jpg"),
        array("id" => "s2004e11", "season" => 2004, "number" => 11, "name" => "Capriccio to Destruction! The Impending Doom of Sky Island!!", "airdate" => "21 Mar 2004", "runtime" => 25, "rating" => 8.7, "summary" => "Enel's thunderclouds are coming down to Sky Island while the evacuation is half complete.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735094.jpg"),
        array("id" => "s2004e12", "season" => 2004, "number" => 12, "name" => "Guidance from the Sound of a Bell! The Great Warrior and Tales of an Explorer", "airdate" => "28 Mar 2004", "runtime" => 25, "rating" => 7.7, "summary" => "The history of Noland and Kalgara is told, as a flashback from Wyper.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735095.jpg"),
        array("id" => "s2004e13", "season" => 2004, "number" => 13, "name" => "Released from Disgrace! The Tears of the Great Warrior!!", "airdate" => "28 Mar 2004", "runtime" => 25, "rating" => 8, "summary" => "Noland and Kalgara are enjoying themselves, as well as the villagers and Noland's crew, but that changes one day, as the villagers start hating their new friends.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735096.jpg"),
        array("id" => "s2004e14", "season" => 2004, "number" => 14, "name" => "Eternal Friendship! The Bell of Oath Echoes Throughout the Giant Ocean!!", "airdate" => "4 Apr 2004", "runtime" => 25, "rating" => 9, "summary" => "The cause of the hatred is discovered and explained. Meanwhile, Kalgara vows to meet Noland again.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735097.jpg"),
        array("id" => "s2004e15", "season" => 2004, "number" => 15, "name" => "The Destruction of Angel Island! Terror of The Descending Raigou!!", "airdate" => "25 Apr 2004", "runtime" => 25, "rating" => 8.3, "summary" => "Angel Island is destroyed by Enel's attacks. Luffy decides to go and ring the golden bell before Enel takes it away.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735098.jpg"),
        array("id" => "s2004e16", "season" => 2004, "number" => 16, "name" => "Chop Down Giant Jack! The Last Hope of Escaping", "airdate" => "2 May 2004", "runtime" => 25, "rating" => 9.3, "summary" => "Nami finds out a way to get to Enel, by cutting down Giant Jack. Wyper finds out from Robin that Noland has a descendant that is searching for the Gold City, and that's the reason why Luffy wants to ring the Golden Bell.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735099.jpg"),
        array("id" => "s2004e17", "season" => 2004, "number" => 17, "name" => "The Miracle in God's Country! A Love Song Heard by Angels", "airdate" => "9 May 2004", "runtime" => 25, "rating" => 10, "summary" => "Luffy defeats Enel, ringing the Golden Bell in the process.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735100.jpg"),
        array("id" => "s2004e18", "season" => 2004, "number" => 18, "name" => "The Battle Ends! Proud Fantasia Echoes Far!", "airdate" => "23 May 2004", "runtime" => 25, "rating" => 9, "summary" => "The 400 year war on Sky Island comes to an end. Montblanc Cricket and the Masira Brothers hear the Golden Bell ringing and realize that the Gold City was always in the sky. Enel, who was thrown to the Blue Sea heads out to the Fairy Vearth (the Moon). The Sky…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735102.jpg"),
        array("id" => "s2004e19", "season" => 2004, "number" => 19, "name" => "I Have Come Here! The Weaving of the Poneglyphs", "airdate" => "6 Jun 2004", "runtime" => 25, "rating" => 9.8, "summary" => "Robin deciphers the poneglyphs on the Golden Bell and realizes how to find the Rio Poneglyph. She also discovers that the poneglyphs on the Bell were written by Gol D. Roger, who could understand poneglyphs, who had discovered the Rio Poneglyph, and had once…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735104.jpg"),
        array("id" => "s2004e20", "season" => 2004, "number" => 20, "name" => "Now Heading Towards the Blue Sea! Memories of an Interwoven Finale", "airdate" => "13 Jun 2004", "runtime" => 25, "rating" => 9.7, "summary" => "The Golden Bell rings as the Straw Hats are going down to the sea, meaning that they are welcome and are deeply thankful for what they did. When the ship finally rests on the sea, problems appear, as the ship has landed in a Marine base.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735106.jpg"),
        array("id" => "s2004e21", "season" => 2004, "number" => 21, "name" => "Emergency Announcement! An Infamous Pirate Ship has Invaded!", "airdate" => "20 Jun 2004", "runtime" => 25, "rating" => 7.7, "summary" => "The Marines are convinced the Going Merry is a ghost ship after it crashes inside their fortress from above. The crew members are scattered around the premises.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735120.jpg"),
        array("id" => "s2004e22", "season" => 2004, "number" => 22, "name" => "Sanji the Chef! Demonstrating True Pride at the Marine Mess Hall!", "airdate" => "27 Jun 2004", "runtime" => 25, "rating" => 7.7, "summary" => "In disguise, Sanji shows the Marine chefs the proper way to prepare a meal.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735121.jpg"),
        array("id" => "s2004e23", "season" => 2004, "number" => 23, "name" => "Zoro's Imprisonment and Chopper's Emergency Operation!", "airdate" => "11 Jul 2004", "runtime" => 25, "rating" => 7.3, "summary" => "Zoro is taken prisoner as Chopper and Nami assist a nervous doctor in treating injured Marines.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735122.jpg"),
        array("id" => "s2004e24", "season" => 2004, "number" => 24, "name" => "The Marine Search Party Draws Near! Another of the Crew is Captured!", "airdate" => "18 Jul 2004", "runtime" => 25, "rating" => 8.3, "summary" => "Robin and Usopp both disguise themselves as the same visiting inspector, and Usopp is thrown in the brig with Zoro. Luffy and Sanji are discovered by Jonathan after a slight mishap.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735123.jpg"),
        array("id" => "s2004e25", "season" => 2004, "number" => 25, "name" => "Luffy and Sanji's Determination! The Great Escape Plan!", "airdate" => "8 Aug 2004", "runtime" => 25, "rating" => 8.3, "summary" => "The real Inspector is thrown in the brig with Zoro and Usopp, while Sanji and Luffy race to rescue the two while avoiding detection.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735124.jpg"),
        array("id" => "s2004e26", "season" => 2004, "number" => 26, "name" => "The Squadron of Burning Souls Attack! Battle on the Bridge!", "airdate" => "5 Sep 2004", "runtime" => 25, "rating" => 6.5, "summary" => "Sanji and Luffy, after freeing Usopp and Zoro, try to escape Navarone. As the Burning Soul combat unit is deployed, Dr. Kobato leads Nami and Chopper to the docks.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735125.jpg"),
        array("id" => "s2004e27", "season" => 2004, "number" => 27, "name" => "Breaking Through Enemy Lines! The Rescue of the Going Merry!", "airdate" => "12 Sep 2004", "runtime" => 25, "rating" => 8.7, "summary" => "The crew meets at the docks and are surrounded by Marines. Using Nami as their fake hostage, they trick the Marines into letting them back on the Going Merry.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735126.jpg"),
        array("id" => "s2004e28", "season" => 2004, "number" => 28, "name" => "The Pirate Ship Disappears! Stronghold Battle, Round 2", "airdate" => "19 Sep 2004", "runtime" => 25, "rating" => 8, "summary" => "The crew disguises the Going Merry as a Marine ship so they can get their treasure back. With the gold, they decide they'll hire a shipwright.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735127.jpg"),
        array("id" => "s2004e29", "season" => 2004, "number" => 29, "name" => "Operation Gold Recovery and Operation Waver Retrieval!", "airdate" => "3 Oct 2004", "runtime" => 25, "rating" => 8.3, "summary" => "Usopp splits up the crew into two teams: the gold retrieval team and the waver retrieval team. Inspector Shepherd decides to catch Luffy on his own.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735128.jpg"),
        array("id" => "s2004e30", "season" => 2004, "number" => 30, "name" => "The Pirate Round-Up Plan! Jonathon's Secret Winning Strategy!", "airdate" => "3 Oct 2004", "runtime" => 25, "rating" => 8, "summary" => "The Straw Hats continue to search for their treasure. Luffy leads Nami to the captain's quarters where they retrieve their gold.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735129.jpg"),
        array("id" => "s2004e31", "season" => 2004, "number" => 31, "name" => "So Long, Marine Base! The Final Battle for Freedom", "airdate" => "10 Oct 2004", "runtime" => 25, "rating" => 9, "summary" => "The Going Merry is grounded during a period of low tide and Jonathan believes they've reached \"checkmate\". They cleverly use the impact dial to boost the ship and the breath and flame dials to inflate the octopus balloon again so they can escape.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735130.jpg"),
        array("id" => "s2004e32", "season" => 2004, "number" => 32, "name" => "Big Adventure in Long Ring Long Land", "airdate" => "31 Oct 2004", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy and company come across a mysterious pirate ship after trying to escape a giant wave. Soon, they arrive on an island inhabited by strange animals. Going Merry is captured by the Foxy Pirate crew.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735415.jpg"),
        array("id" => "s2004e33", "season" => 2004, "number" => 33, "name" => "The Foxy Pirate Crew and the Davy Back!", "airdate" => "7 Nov 2004", "runtime" => 25, "rating" => 8, "summary" => "After Tonjit re-unites with his horse, they are soon attacked by Captain Foxy and his subordinates, who challenge Luffy in a Davy Back Fight, a contest of pirates where the stakes are members of the crew.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735416.jpg"),
        array("id" => "s2004e34", "season" => 2004, "number" => 34, "name" => "Round 1! One Lap of the Donut Race", "airdate" => "14 Nov 2004", "runtime" => 25, "rating" => 8, "summary" => "The first round of Davy Back Fight involves a race around the island with tiny boats. Zoro's and Chopper's boat is eliminated.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735417.jpg"),
        array("id" => "s2004e35", "season" => 2004, "number" => 35, "name" => "Foxy the Silver Fox! A Violent Interference", "airdate" => "21 Nov 2004", "runtime" => 25, "rating" => 8, "summary" => "With only Luffy, Nami, and Porche's boat remaining, it's an all out war to the goal, but after Foxy exposes his Devil Fruit powers, Porche wins and takes Tony Tony Chopper from Luffy. The second round prepares to start.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735418.jpg"),
        array("id" => "s2004e36", "season" => 2004, "number" => 36, "name" => "Round 2! Shoot into the Groggy Ring!", "airdate" => "28 Nov 2004", "runtime" => 25, "rating" => 8, "summary" => "Without Chopper, Sanji and Zoro must face the Foxy Pirates in a ball game, but are hampered by their blatant cheating and the crooked referee.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735419.jpg"),
        array("id" => "s2004e37", "season" => 2004, "number" => 37, "name" => "Rapid-Fire Red Cards! Groggy Ring", "airdate" => "5 Dec 2004", "runtime" => 25, "rating" => 8, "summary" => "The bickering rivals Sanji and Zoro manage to overcome the opposing team by working together. Luffy chooses Tonjit's horse, Shelly over Chopper.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735420.jpg"),
        array("id" => "s2004e38", "season" => 2004, "number" => 38, "name" => "Round 3! Round and Round Roller Race!", "airdate" => "12 Dec 2004", "runtime" => 25, "rating" => 8, "summary" => "The Straw Hats face Foxy a race around a giant ring on roller skates.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735421.jpg"),
        array("id" => "s2004e39", "season" => 2004, "number" => 39, "name" => "Burning Roller Race! Dash into the Final Round!", "airdate" => "19 Dec 2004", "runtime" => 25, "rating" => 8.3, "summary" => "The Straw Hat Pirates stop Foxy and his dirty tricks and win the race. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735422.jpg"),
    )),
    array("number" => 2005, "name" => "#215 - #253", "rating" => 8.6, "episodes" => array(
        array("id" => "s2005e1", "season" => 2005, "number" => 1, "name" => "The Screaming Speed Serve! Pirate Dodgeball!", "airdate" => "9 Jan 2005", "runtime" => 25, "rating" => 8.5, "summary" => "With Luffy's victory, he takes Chopper back, but foolishly accepts another challenge by Foxy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735423.jpg"),
        array("id" => "s2005e2", "season" => 2005, "number" => 2, "name" => "Final Match on the Edge! Dharma has Fallen!", "airdate" => "9 Jan 2005", "runtime" => 25, "rating" => 8.3, "summary" => "Foxy decides to take Robin from Luffy this time because of her Devil Fruit ability. The next match is a race to the top of the island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735424.jpg"),
        array("id" => "s2005e3", "season" => 2005, "number" => 3, "name" => "Captain Confrontation! The Last Fight: Combat!", "airdate" => "16 Jan 2005", "runtime" => 25, "rating" => 8, "summary" => "With Chopper gone again from Luffy's crew, Luffy and Foxy face off in the final game: a battle of brawn aboard Foxy's ship.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735426.jpg"),
        array("id" => "s2005e4", "season" => 2005, "number" => 4, "name" => "Full Power Noro Noro Beam vs The Invulnerable Luffy", "airdate" => "23 Jan 2005", "runtime" => 25, "rating" => 8, "summary" => "Luffy continues to battle Foxy with the odds not in his favor, and the fight continues inside Foxy's ship.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735427.jpg"),
        array("id" => "s2005e5", "season" => 2005, "number" => 5, "name" => "Heroic Fierce Combat! The Fateful Last Battle", "airdate" => "30 Jan 2005", "runtime" => 25, "rating" => 7.6, "summary" => "Luffy manages to finally defeat Foxy by using his ability against him. After dismissing his new crewmembers, the Straw Hats leave in search for a shipwright.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735428.jpg"),
        array("id" => "s2005e6", "season" => 2005, "number" => 6, "name" => "Lost? Stolen? Who are You?", "airdate" => "6 Feb 2005", "runtime" => 25, "rating" => 6, "summary" => "A mysterious figure appears during the night and steals the memories of the crew. In the morning, Robin is the only one who remembers the Straw Hats adventures together. Her attempts to keep the crew together fail as Nami and Zoro go separate ways.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735429.jpg"),
        array("id" => "s2005e7", "season" => 2005, "number" => 7, "name" => "The Mysterious Boy with the Whistle and Robin's Guess", "airdate" => "13 Feb 2005", "runtime" => 25, "rating" => 6, "summary" => "Robin suggests that only those who were sleeping lost their memories. Luffy and the others then remember seeing the mysterious boy who played some kind of flute. Later that night, they discover the boy outside and Luffy tries to fight him. At the last second,…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735430.jpg"),
        array("id" => "s2005e8", "season" => 2005, "number" => 8, "name" => "Get Back the Memories! The Pirates Land", "airdate" => "20 Feb 2005", "runtime" => 25, "rating" => 6, "summary" => "During the night, Usopp, Chopper, and Sanji question what brought them to the Going Merry. In the morning, Usopp builds them a raft and they sail to the island where they meet Nami again. Meanwhile, the boy sets his sights on Zoro.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735431.jpg"),
        array("id" => "s2005e9", "season" => 2005, "number" => 9, "name" => "Zoro Sharpens His Fangs! A Fight with a Wild Animal", "airdate" => "27 Feb 2005", "runtime" => 25, "rating" => 6, "summary" => "On their way to \"The Palace of the Sea God\" Robin's group meets an entranced Zoro. It looks like Zoro wants to fight so Luffy urges the others to keep going without him. They apprehend the kid but the whistle was what was really stealing their memories. Zoro…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735432.jpg"),
        array("id" => "s2005e10", "season" => 2005, "number" => 10, "name" => "The Real Memory Thief's Final Counterattack!", "airdate" => "6 Mar 2005", "runtime" => 25, "rating" => 6, "summary" => "Luffy returns and knocks some sense into Zoro. Cornered, the sea horse spreads illusions of the people in their memories to distract them. It steals their complete memories and claims that it has become a Sennenryu. Luffy defeats it and returns all the memori…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735433.jpg"),
        array("id" => "s2005e11", "season" => 2005, "number" => 11, "name" => "The Man of Pride! Foxy the Silver Fox", "airdate" => "13 Mar 2005", "runtime" => 25, "rating" => 7.5, "summary" => "Luffy rescues Foxy, Hamburg, and Porche from a storm at sea. When they reunite with the Sexy Foxy ship, they find it captained by somebody new. Foxy accepts a Davy Back Fight in order to regain his ship and crew. Donning the afro once again, Luffy vows to def…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735434.jpg"),
        array("id" => "s2005e12", "season" => 2005, "number" => 12, "name" => "The Unbeatable Power Draws Near? A Very Dangerous Man!", "airdate" => "20 Mar 2005", "runtime" => 25, "rating" => 8.3, "summary" => "Once Foxy wins back his crew, he captures the Straw Hats. Nami and Luffy fight Foxy and although he's defeated, his crew accepts him back. Later, they sail to an island where they meet someone Robin knows: a Marine named Aokiji.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735435.jpg"),
        array("id" => "s2005e13", "season" => 2005, "number" => 13, "name" => "Marine High Admiral Aokiji! The Threat of the Greatest Power", "airdate" => "27 Mar 2005", "runtime" => 25, "rating" => 10, "summary" => "The man they met, Marine High Admiral Aokiji, appears to be incredibly lazy. He first displays his Devil's Fruit ability by freezing the sea so some deserted people can get off the island. Unfortunately, he's determined to catch Robin. Luffy, Sanji, and Zoro…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735436.jpg"),
        array("id" => "s2005e14", "season" => 2005, "number" => 14, "name" => "Rubber and Ice One-On-One Fight! Luffy vs Aokiji!", "airdate" => "27 Mar 2005", "runtime" => 25, "rating" => 10, "summary" => "Luffy insists on fighting Aokiji alone and risks it all so the crew can save the frozen Robin. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735437.jpg"),
        array("id" => "s2005e15", "season" => 2005, "number" => 15, "name" => "Running Sea Train! The City of Water, Water 7", "airdate" => "17 Apr 2005", "runtime" => 25, "rating" => 8.5, "summary" => "After the Going Merry narrowly escapes being hit by a Sea Train, the crew meets an old woman, Kokoro, and her granddaughter, Chimney. Kokoro gives Luffy a map to Water 7.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735438.jpg"),
        array("id" => "s2005e16", "season" => 2005, "number" => 16, "name" => "The Adventure in the City of Water! Aim for the Giant Shipyard", "airdate" => "24 Apr 2005", "runtime" => 25, "rating" => 9, "summary" => "Luffy, Nami, and Usopp get strange greetings from the residents and they get to experience the roller coaster-like channels of Water 7. Luffy's group finds out that some pirates had been beaten at the hands of some powerful craftsmen; the Galley La Company. C…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735439.jpg"),
        array("id" => "s2005e17", "season" => 2005, "number" => 17, "name" => "The Franky Family and Iceburg!", "airdate" => "1 May 2005", "runtime" => 25, "rating" => 8.8, "summary" => "The people who attacked Zoro reveal themselves to be the feared \"Franky Family\", though they are no match for Zoro. Luffy's group has the gold exchanged for cash. After, they meet a man who resembles Usopp, Galley La's carpenter employment foreman, Kaku. Two…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735440.jpg"),
        array("id" => "s2005e18", "season" => 2005, "number" => 18, "name" => "Galley-La Company! The Magnificent Dock #1", "airdate" => "15 May 2005", "runtime" => 25, "rating" => 8.8, "summary" => "Paulie makes his debut when he retrieves Usopp's stolen money as he runs from debt collectors. Kalifa shows Luffy, Nami, and Usopp around Dock No.1 and tells them how Iceburg founded the Galley La Company. Kaku returns from the Going Merry and tells them that…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735441.jpg"),
        array("id" => "s2005e19", "season" => 2005, "number" => 19, "name" => "The Pirate Kidnapping Incident and the Pirate Ship Waits for Death!", "airdate" => "22 May 2005", "runtime" => 25, "rating" => 9, "summary" => "Luffy refuses to believe that Galley La cannot repair the Going Merry. The two soon realize that not only is Usopp missing now, the two brief cases that were returned to them are empty! Nami decides to head to Franky House and finds Usopp on the way in a piti…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735442.jpg"),
        array("id" => "s2005e20", "season" => 2005, "number" => 20, "name" => "Rescuing a Friend! The Raid on the Franky House", "airdate" => "5 Jun 2005", "runtime" => 25, "rating" => 9.8, "summary" => "Luffy, Sanji, Zoro, and Chopper follow Usopp's bloody trail to the Franky House where they find him passed out in front. The four of them challenge the Franky Family only to find out that their real target, Franky himself, is gone and has taken the money with…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735443.jpg"),
        array("id" => "s2005e21", "season" => 2005, "number" => 21, "name" => "Quarrel in the Moonlight! The Pirate Ship Trembles in Sadness", "airdate" => "12 Jun 2005", "runtime" => 25, "rating" => 10, "summary" => "Once they are back on the ship, Luffy has to finally tell Usopp that the Going Merry can no longer be repaired and that they've chosen to get a new ship without him. Usopp believes that Luffy has abandoned the dignity of their ship and says he's leaving the c…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735444.jpg"),
        array("id" => "s2005e22", "season" => 2005, "number" => 22, "name" => "Luffy vs Usopp! The Spirit of the Clashing Men", "airdate" => "19 Jun 2005", "runtime" => 25, "rating" => 10, "summary" => "Usopp fights Luffy in order to decide who keeps the Going Merry; he fights harder than he's ever fought before. Luffy actually seems to pose no threat but all the while, he's remembering what great friends they used to be, sailing together on the same ship.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735445.jpg"),
        array("id" => "s2005e23", "season" => 2005, "number" => 23, "name" => "The City of Water is Shaking! Iceburg was Targeted!", "airdate" => "3 Jul 2005", "runtime" => 25, "rating" => 8.5, "summary" => "The Straw Hats get themselves a hotel room. Nami finds the crew on the roof with urgent news; Iceburg has been shot. As the Galley La Company frantically search for answers, Nami and Luffy decide to check on his condition - only to be met by closed gates. Fra…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735446.jpg"),
        array("id" => "s2005e24", "season" => 2005, "number" => 24, "name" => "Rubberman vs Fire-Breathing Cyborg", "airdate" => "10 Jul 2005", "runtime" => 25, "rating" => 9, "summary" => "In the streets outside of the hospital, Luffy fights Franky. Inside, Iceburg recalls seeing Nico Robin and another tall man before he was shot. The Galley La company run outside and stop Franky and Luffy and tell them that they suspect the Straw Hat Pirates o…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735447.jpg"),
        array("id" => "s2005e25", "season" => 2005, "number" => 25, "name" => "The Criminals are the Straw Hat Pirates? The Bodyguards of Water 7", "airdate" => "31 Jul 2005", "runtime" => 25, "rating" => 8.8, "summary" => "The Galley La Company continues to fight Luffy and Franky is enraged that they've stolen his opponent. An incredibly high tide called the \"Aqua Laguna\" is coming and Chopper and Sanji rush to warn Usopp. Luffy raises some chaos in order to meet with Iceburg a…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735448.jpg"),
        array("id" => "s2005e26", "season" => 2005, "number" => 26, "name" => "An Eternal Farewell? Nico Robin, The Woman Who Bears Darkness", "airdate" => "7 Aug 2005", "runtime" => 25, "rating" => 9, "summary" => "In a bar, Franky talks with Kokoro about her theory on who shot Iceburg. The rumors she speaks of seem to have some truth as we see Robin meeting with someone from an organization called CP9. While the crew hide from angry residents, Sanji and Chopper discove…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735449.jpg"),
        array("id" => "s2005e27", "season" => 2005, "number" => 27, "name" => "Catch Robin! The Determination of the Straw Hat Pirates", "airdate" => "14 Aug 2005", "runtime" => 25, "rating" => 8.3, "summary" => "Chopper reunites with the others without Sanji and they discuss what's happened. Luffy decides that in order to know the full truth, they must catch Robin. Usopp attempts to repair the ship enough to withstand the Aqua Laguna and the Straw Hats make their way…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735450.jpg"),
        array("id" => "s2005e28", "season" => 2005, "number" => 28, "name" => "The Signal is the Explosion! CP9 Starts to Move", "airdate" => "21 Aug 2005", "runtime" => 25, "rating" => 9.5, "summary" => "The Straw Hats (still missing Sanji) rush to Galley La where Robin and CP9 begin a raid. In Iceburg's room, Robin and the mysterious man Iceburg saw before, tell him that they've purposely placed the blame on the pirates. Their true aim is the blueprints he w…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735451.jpg"),
        array("id" => "s2005e29", "season" => 2005, "number" => 29, "name" => "CP9 Unmasked! Their Shocking True Faces", "airdate" => "4 Sep 2005", "runtime" => 25, "rating" => 9.5, "summary" => "Robin speaks with Iceburg inside his room still. We already know that Robin can read the poneglyphs - and it seems Iceburg is the one with the blueprints to the ultimate weapon, Pluton. The true enemies are revealed to be Iceburg's own allies. Elsewhere, Luff…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735452.jpg"),
        array("id" => "s2005e30", "season" => 2005, "number" => 30, "name" => "The Secret Bond! Franky and Iceburg", "airdate" => "11 Sep 2005", "runtime" => 25, "rating" => 9.8, "summary" => "Lucci tells Iceburg their hypothesis and has Kaku check his pulse to tell if the things he tells him are true. They suspect that Iceburg's friend from the past, Cutty Flam, is really Franky and it's revealed to be true. Therefore, Franky has the real blueprin…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735453.jpg"),
        array("id" => "s2005e31", "season" => 2005, "number" => 31, "name" => "Come Back, Robin! The Confrontation with CP9", "airdate" => "18 Sep 2005", "runtime" => 25, "rating" => 9.5, "summary" => "Luffy and the others request that Robin comes back to the crew. She refuses and tells them that she cannot accomplish her \"wish\" if she were to stay with them. Robin turns to leave and CP9 try to hold the pirates back. Robin successfully escapes and Lucci sho…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735454.jpg"),
        array("id" => "s2005e32", "season" => 2005, "number" => 32, "name" => "Destruction of the Straw Hat Pirates? The Terror of the Model Leopard!", "airdate" => "23 Oct 2005", "runtime" => 25, "rating" => 8.8, "summary" => "Lucci's transformation is a result of a Devil's Fruit; a Zoan Type leopard. He quickly disposes of the crew and CP9 tie up Paulie and Iceburg, leaving them alone as the building slowly burns down around them. In Franky's underground hideout, Usopp tells him h…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735455.jpg"),
        array("id" => "s2005e33", "season" => 2005, "number" => 33, "name" => "The Man who is Loved by his Ship! Usopp's Tears!", "airdate" => "30 Oct 2005", "runtime" => 25, "rating" => 8.5, "summary" => "Usopp believes that the person who repaired the Going Merry in Skypeia was really the Going Merry itself. Franky says that the ship was inhabited by a spirit who enters ships who are dearly cared for. The spirit repaired their ship just enough for them to rea…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735456.jpg"),
        array("id" => "s2005e34", "season" => 2005, "number" => 34, "name" => "Franky's Past! The Day the Sea Train Ran", "airdate" => "6 Nov 2005", "runtime" => 25, "rating" => 9.8, "summary" => "CP9 discover Franky's hidden room and he fears they'll trample his memories. A long flashback ensues, covering Franky's past in Tom's Workers and how he and Iceburg helped create the Sea Train.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735458.jpg"),
        array("id" => "s2005e35", "season" => 2005, "number" => 35, "name" => "Spandam's Conspiracy! The Day the Sea Train Shook", "airdate" => "13 Nov 2005", "runtime" => 25, "rating" => 9.5, "summary" => "(Franky's flashback) Spandam, a CP5 representative, was determined to get Tom proven guilty in his trial so he could get the blueprints. As Franky walked into the town, people from the government began to attack with the battleships he had personally construc…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735460.jpg"),
        array("id" => "s2005e36", "season" => 2005, "number" => 36, "name" => "The End of the Legendary Man! The Day the Sea Train Cried", "airdate" => "27 Nov 2005", "runtime" => 25, "rating" => 10, "summary" => "(Franky's flashback) Franky said that if a ship of his were to be used as a weapon, then it's no longer one of his ships. That enraged Tom and he punched Franky for the first time, telling him he had to take pride in the ships he created. He then told the jud…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735461.jpg"),
        array("id" => "s2005e37", "season" => 2005, "number" => 37, "name" => "The Truth Behind the Betrayal! Robin's Sorrowful Decision!", "airdate" => "27 Nov 2005", "runtime" => 25, "rating" => 9.5, "summary" => "Chopper escapes the burning building with Paulie and Iceburg on his back and collapses outside. Iceburg makes it clear to Nami that Robin wanted to recover the blueprints and to do that, she wanted her companions to leave the island without her. Nami rushes t…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735462.jpg"),
        array("id" => "s2005e38", "season" => 2005, "number" => 38, "name" => "The Steam Whistle Separates the Group! The Sea Train Begins to Run", "airdate" => "4 Dec 2005", "runtime" => 25, "rating" => 9, "summary" => "Paulie helps clear the name of the Straw Hats but does not tell the mob everything he knows. He gets the mob to follow Chopper so they can search for the rest of the crew. Nami goes her own way so she can rush to the Sea Train. As Nami nears the station, Sanj…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735463.jpg"),
        array("id" => "s2005e39", "season" => 2005, "number" => 39, "name" => "Sanji Breaks In! The Sea Train Battle in the Storm!", "airdate" => "11 Dec 2005", "runtime" => 25, "rating" => 8.5, "summary" => "Nami and the conductors are rescued by Paulie when the Aqua Laguna floods the main station. A man hands Nami a letter he found from Sanji. It informs her that Usopp, Franky, and he are on board the train that had just departed. On board, he storms the cars. H…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735464.jpg"),
    )),
    array("number" => 2006, "name" => "#254 - #291", "rating" => 8.6, "episodes" => array(
        array("id" => "s2006e1", "season" => 2006, "number" => 1, "name" => "The Shout of Nami's Soul! The Return of the Straw Hat!", "airdate" => "22 Jan 2006", "runtime" => 25, "rating" => 8.8, "summary" => "Nami finally reaches Luffy and tells him that he needs to hurry before Robin reaches Enies Lobby. Chopper finds Zoro and hands him the Sandai Kitetsu so he can escape the chimney. Luffy pushes apart the buildings he was stuck between and Paulie grabs them all…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735465.jpg"),
