        array("id" => "s2008e31", "season" => 2008, "number" => 31, "name" => "One Down!! Sure Kill Straw Hat Docking?", "airdate" => "24 Aug 2008", "runtime" => 25, "rating" => 9.6, "summary" => "Nami attempts to track down some missing treasure; Brook searches the kitchen for a mystery ingredient; a heroic team battle against Oars in a effort to topple him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735871.jpg"),
        array("id" => "s2008e32", "season" => 2008, "number" => 32, "name" => "Soundless Invasion!! The Mysterious Visitor: Kuma the Tyrant", "airdate" => "31 Aug 2008", "runtime" => 25, "rating" => 9, "summary" => "Nami chases after Perona, who is fleeing from Thriller Bark; Kuma arrives and wrecks the place.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735872.jpg"),
        array("id" => "s2008e33", "season" => 2008, "number" => 33, "name" => "Oars + Moria - The Greatest Combination of Brains and Brawn", "airdate" => "7 Sep 2008", "runtime" => 25, "rating" => 9.2, "summary" => "Luffy discovers that he has been chasing Gekko's shadow wile the real Gekko escaped.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735873.jpg"),
        array("id" => "s2008e34", "season" => 2008, "number" => 34, "name" => "A Crazy Strategy to Turn the Tables - The Creation of Nightmare Luffy", "airdate" => "14 Sep 2008", "runtime" => 25, "rating" => 9.6, "summary" => "Oars manages to turn the tide of the battle by countering the Straw Hats; Nami arrives and joins the fight; Luffy meets some interesting individuals who might be of help.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735874.jpg"),
        array("id" => "s2008e35", "season" => 2008, "number" => 35, "name" => "The Straw Hat Crew annihilated! Full-throttle Kage Kage abilities!", "airdate" => "21 Sep 2008", "runtime" => 25, "rating" => 7.6, "summary" => "Brook joins the fight; the Straw Hats try to hold off Oars and Moria until Luffy is able to return but they may not be able to.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735875.jpg"),
        array("id" => "s2008e36", "season" => 2008, "number" => 36, "name" => "The Battle for Superiority Starts! Luffy vs. Luffy", "airdate" => "28 Sep 2008", "runtime" => 25, "rating" => 9.2, "summary" => "While Oars and Moria is ruthlessly pummeling the Straw Hat pirates, Nightmare Luffy arrives to join the battle.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735876.jpg"),
