        array("id" => "s2008e38", "season" => 2008, "number" => 38, "name" => "The Bodies Vanish! The Morning Sun Pierces Through the Nightmare Island!", "airdate" => "12 Oct 2008", "runtime" => 25, "rating" => 9.2, "summary" => "Moria gobbles up every shadow in sight to power up for the final showdown with Luffy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735879.jpg"),
        array("id" => "s2008e39", "season" => 2008, "number" => 39, "name" => "The Endless Crisis! Orders to Obliterate the Straw Hat Crew", "airdate" => "19 Oct 2008", "runtime" => 25, "rating" => 9.2, "summary" => "The battle between Luffy and Moria reaches it's end; Kuma causes panic on the island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735880.jpg"),
        array("id" => "s2008e40", "season" => 2008, "number" => 40, "name" => "It Repels Everything! Kuma's Paw-Paw Power!", "airdate" => "9 Nov 2008", "runtime" => 25, "rating" => 9.6, "summary" => "The World Government orders Kuma to obliterate every living being on the island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/431/1078159.jpg"),
        array("id" => "s2008e41", "season" => 2008, "number" => 41, "name" => "My Companions' Pain is My Pain - Zoro Prepares to Die", "airdate" => "16 Nov 2008", "runtime" => 25, "rating" => 9.9, "summary" => "A heated confrontation occurs when Zoro and Sanji have to make a decision so they can save Luffy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735882.jpg"),
