        array("id" => "s2008e43", "season" => 2008, "number" => 43, "name" => "Brook's Past - Sad Farewell to the Cheerful Crew", "airdate" => "30 Nov 2008", "runtime" => 25, "rating" => 9.8, "summary" => "Brook recalls his past, when the whale Laboon started following his pirate ship and befriended the crew.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735884.jpg"),
