        array("id" => "s2008e45", "season" => 2008, "number" => 45, "name" => "A New Crewmate! Musician - The Hummer Brook", "airdate" => "14 Dec 2008", "runtime" => 25, "rating" => 9.3, "summary" => "Brook pledges himself to the Straw Hat Pirates, becoming their ninth member, as the crew settles their affairs at Thriller Bark and continue their journey.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735886.jpg"),
        array("id" => "s2008e46", "season" => 2008, "number" => 46, "name" => "Noro Noro Menace - Return of Foxy the Silver Fox", "airdate" => "21 Dec 2008", "runtime" => 25, "rating" => 7, "summary" => "The Straw Hat Pirates are taking a vacation at Spa Island, but there, they encounter Foxy and his crew, who are pursuing two small girls: Lina and her older sister, Sayo.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735888.jpg"),
