    array("number" => 2009, "name" => "#384 - #432", "rating" => 8.5, "episodes" => array(
        array("id" => "s2009e1", "season" => 2009, "number" => 1, "name" => "Brook's Hard Struggle - The Difficult Path to Becoming a True Nakama", "airdate" => "11 Jan 2009", "runtime" => 25, "rating" => 8.1, "summary" => "Brook tries to help his new nakamas because he fears that otherwise he will be dispensed, but Robin tell him her story of Water 7 and he recovers his confidence.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735890.jpg"),
        array("id" => "s2009e2", "season" => 2009, "number" => 2, "name" => "Arriving at Halfway Through the Grand Line! The Red Line", "airdate" => "18 Jan 2009", "runtime" => 25, "rating" => 8.7, "summary" => "The Straw Hat Pirates are about to reach the Red Line but a terrible storm delays them. Log Pose is pointing downwards and the crew needs more information to get to Gyojin Island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735901.jpg"),
