        array("id" => "s2009e4", "season" => 2009, "number" => 4, "name" => "The Fated Reunion! Save the Imprisoned Fishman", "airdate" => "1 Feb 2009", "runtime" => 25, "rating" => 7.6, "summary" => "The mysterious Duval gets excited when the crew that rescued Camie turns out to be the Straw Hat Pirates.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735903.jpg"),
        array("id" => "s2009e5", "season" => 2009, "number" => 5, "name" => "Tragedy! The Truth of the Unmasked Duval", "airdate" => "8 Feb 2009", "runtime" => 25, "rating" => 8.3, "summary" => "The Straw Hat Pirates do battle with the Flying Fish Riders and Macro Fishman Pirates. The stakes rise when Duval reveals himself, and exactly who his grudge is against: Sanji.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735904.jpg"),
        array("id" => "s2009e6", "season" => 2009, "number" => 6, "name" => "Explosion! The Sunny's Super Secret Weapon: Gaon Cannon", "airdate" => "15 Feb 2009", "runtime" => 25, "rating" => 8.1, "summary" => "Duval reveals that he was once a small-time bandit until Sanji's wanted poster came to light. Since then he hid his face with the iron mask until he could get revenge on Sanji.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735905.jpg"),
        array("id" => "s2009e7", "season" => 2009, "number" => 7, "name" => "Landing to Get to Fishman Island - The Sabaody Archipelago", "airdate" => "22 Feb 2009", "runtime" => 25, "rating" => 8.7, "summary" => "With the Flying Fish Riders taken care of, the Straw Hats rest as Hatchan treats them to the promised takoyaki.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735906.jpg"),
