        array("id" => "s2009e9", "season" => 2009, "number" => 9, "name" => "New Rivals Gather! The 11 Supernovas", "airdate" => "8 Mar 2009", "runtime" => 25, "rating" => 9.3, "summary" => "The Straw Hat Pirates fight and defeat some bounty hunters who want their bounty.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735908.jpg"),
