        array("id" => "s2009e12", "season" => 2009, "number" => 12, "name" => "Time Limit - The Human Auction Begins", "airdate" => "5 Apr 2009", "runtime" => 25, "rating" => 9, "summary" => "The human auction finally begins, and it is only then that the Straw Hats discovered that their mermaid friend is being sold off at Grove 1.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735911.jpg"),
