        array("id" => "s2009e15", "season" => 2009, "number" => 15, "name" => "Admiral Kizaru Moves! The Sabaody Archipelago in Chaos", "airdate" => "26 Apr 2009", "runtime" => 25, "rating" => 9.3, "summary" => "Sengoku dispatches Admiral Kizaru to defend the honor of the Celestial Dragons at Sabaody Archipelago.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735914.jpg"),
