        array("id" => "s2009e20", "season" => 2009, "number" => 20, "name" => "Another Strong Enemy Appears! Broadaxe-Wielding Sentomaru", "airdate" => "31 May 2009", "runtime" => 25, "rating" => 9.3, "summary" => "The Straw Hat Pirates combine their strongest attacks to defeat the Pacifista, but are exhausted after the battle.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735919.jpg"),
        array("id" => "s2009e21", "season" => 2009, "number" => 21, "name" => "Admiral Kizaru's Fierce Attack. The Straw Hat Crew's Desperate Situation!", "airdate" => "7 Jun 2009", "runtime" => 25, "rating" => 9.3, "summary" => "Usopp and Brook's attempt to attack Kizaru and save Zoro's life failed.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735920.jpg"),
