        array("id" => "s2009e26", "season" => 2009, "number" => 26, "name" => "Hurry! Get back to your friends. Adventure on the Island of Women.", "airdate" => "12 Jul 2009", "runtime" => 25, "rating" => 7.9, "summary" => "It is revealed that Luffy is on Amazon Lily, an island populated entirely by the Kuja tribe of women warriors.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735925.jpg"),
