        array("id" => "s2009e28", "season" => 2009, "number" => 28, "name" => "The Secret Hidden on Their Backs, Luffy Encounters The Princess", "airdate" => "2 Aug 2009", "runtime" => 25, "rating" => 8.2, "summary" => "Boa Hancock's ship reaches Amazon Lily and she returns to her palace.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735927.jpg"),
