        array("id" => "s2009e31", "season" => 2009, "number" => 31, "name" => "Battle with Full-Powered Abilities! Gomu Gomu vs. Hebi Hebi", "airdate" => "23 Aug 2009", "runtime" => 25, "rating" => 8.7, "summary" => "Luffy activates Gear Second and is currently taking the lead.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735930.jpg"),
