        array("id" => "s2009e34", "season" => 2009, "number" => 34, "name" => "Love is a Hurricane! Hancock Madly in Love", "airdate" => "13 Sep 2009", "runtime" => 25, "rating" => 9.2, "summary" => "When Nyon visits Hancock, she deduces her illness and when she mentions Luffy wishes to see her, this causes Hancock to get up and speak with him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735933.jpg"),
