        array("id" => "s2009e36", "season" => 2009, "number" => 36, "name" => "The Crew's Whereabouts - The Island of Giant Birds and the Pink Paradise!", "airdate" => "27 Sep 2009", "runtime" => 25, "rating" => 7.3, "summary" => "Chopper is awakened by giant birds that want to use him as a toy. Meanwhile, Sanji wakes up in the lap of a beautiful \"woman\" on an island thats makes everything girly.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735935.jpg"),
        array("id" => "s2009e37", "season" => 2009, "number" => 37, "name" => "The Crew's Whereabouts - The Bridge that Connects Islands and Man-Eating Plants", "airdate" => "4 Oct 2009", "runtime" => 25, "rating" => 8, "summary" => "Robin is found unconscious by Soran in the snow on the Tequila Wolf, a huge bridge that has been under construction for over 700 years. Usopp is chased by a large beetle, but he is saved by a man named Heracles. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735936.jpg"),
        array("id" => "s2009e38", "season" => 2009, "number" => 38, "name" => "The Crew's Whereabouts - The Negative Princess and the Devil King!", "airdate" => "11 Oct 2009", "runtime" => 25, "rating" => 8.8, "summary" => "Zoro lands on the island where Kuma also sent Perona, who treats his wounds. Brook finds himself on Namakura Island, where he is mistaken for Satan, whom the islanders had summoned for revenge against the Longarm Tribe. Meanwhile, the Marines gather at Marine…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735937.jpg"),
