        array("id" => "s2009e40", "season" => 2009, "number" => 40, "name" => "A Reunion in Hell?! The Man Who Ate the Chop-Chop Fruit!", "airdate" => "25 Oct 2009", "runtime" => 25, "rating" => 8.7, "summary" => "Hancock turns Domino to stone before she can undergo the body-check, allowing Luffy to escape into the prison.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/735940.jpg"),
