        array("id" => "s2012e5", "season" => 2012, "number" => 5, "name" => "The Ryugu Palace In Shock! The Kidnapping Of Shirahoshi!", "airdate" => "5 Feb 2012", "runtime" => 25, "rating" => 8.9, "summary" => "Luffy leads Shirahoshi out of her tower inside Megalo while Brook and the Minister of the Right tells them to stop.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736525.jpg"),
