        array("id" => "s2012e7", "season" => 2012, "number" => 7, "name" => "The Battle In The Ryugu Palace! Zoro Vs. Hordy!", "airdate" => "19 Feb 2012", "runtime" => 25, "rating" => 9, "summary" => "Neptune begs someone to protect her daughter. Hody just comments on how weak he is and states he only joined his army for military strength and knowledge. He states he will revive the dream and ambition of Arlong.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736527.jpg"),
        array("id" => "s2012e8", "season" => 2012, "number" => 8, "name" => "Keep Shirahoshi Safe! Decken Close Behind!", "airdate" => "26 Feb 2012", "runtime" => 25, "rating" => 9.1, "summary" => "Chopper tries to persuade Sanji to not turn around, or else he will see Shirahoshi and die. But Sanji turns around and after seeing the princess, turns into stone.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736528.jpg"),
        array("id" => "s2012e9", "season" => 2012, "number" => 9, "name" => "The Crew Falls?! Hody Conquers Ryuuguu Palace", "airdate" => "4 Mar 2012", "runtime" => 25, "rating" => 8.9, "summary" => "Zoro cuts Hody and asks for Neptune's help to escape from Ryugu Palace. Unfortunately, Hody who was unconscious comes to his senses after taking an Energy Steroid and successfully stops Neptune and the Straw Hats from escaping.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736529.jpg"),
        array("id" => "s2012e10", "season" => 2012, "number" => 10, "name" => "The Haunting Ties! Nami And The Fishmen Pirates!", "airdate" => "18 Mar 2012", "runtime" => 25, "rating" => 8.4, "summary" => "Robin continues her search while the New Fishman Pirates begin to take over. People are also seen being forced to step on a photo, and if they do not, they are considered as enemies.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736530.jpg"),
        array("id" => "s2012e11", "season" => 2012, "number" => 11, "name" => "A Hero Who Freed The Slaves! An Adventurer Tiger!", "airdate" => "25 Mar 2012", "runtime" => 25, "rating" => 9.1, "summary" => "Otohime confronts a robber who was stealing money so he could buy food for his ten children. Otohime and Jinbe try to change Fishman island, and Jinbe leaves the Army to join the Sun Pirates.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736531.jpg"),
        array("id" => "s2012e12", "season" => 2012, "number" => 12, "name" => "Kizaru Appears! A Trap To Catch Tiger!", "airdate" => "1 Apr 2012", "runtime" => 25, "rating" => 9.1, "summary" => "Entering a flashback, Neptune holds a baby Shirahoshi commenting on Tiger's attack on Mary Geoise, stating he would not be able to attend a summit for a long time because of it.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736532.jpg"),
        array("id" => "s2012e13", "season" => 2012, "number" => 13, "name" => "Toriko x One Piece Special: Team Formation! Save Chopper!", "airdate" => "8 Apr 2012", "runtime" => 25, "rating" => 7.5, "summary" => "Toriko and Komatsu are seen fishing when Komatsu catches a Harusame. After defeating it, Luffy suddenly comes out of the Harusame's mouth and surprises Toriko and Komatsu.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736533.jpg"),
        array("id" => "s2012e14", "season" => 2012, "number" => 14, "name" => "The Death Of The Hero! A Shocking Truth Of Tiger!", "airdate" => "15 Apr 2012", "runtime" => 25, "rating" => 9.4, "summary" => "The Sun Pirates start making their way to Koala's hometown, while giving her a slight makeover, new clothes and cutting her hair. on their ship, Koala still acts like a slave would, doing chores without being asked and asking for orders.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736534.jpg"),
        array("id" => "s2012e15", "season" => 2012, "number" => 15, "name" => "The Sun Pirates Split! Jimbe Vs. Arlong!", "airdate" => "22 Apr 2012", "runtime" => 25, "rating" => 9.1, "summary" => "After Fisher Tiger's death, Arlong, enraged, betrays his last wishes and decides to attack and kill villagers of Koala's village for selling him out, upon trying he is easily beaten by Vice-Admiral Borsalino and taken into Marine custody.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736535.jpg"),
        array("id" => "s2012e16", "season" => 2012, "number" => 16, "name" => "Shaking Fishman Island! A Celestial Dragon Drifts In!", "airdate" => "29 Apr 2012", "runtime" => 25, "rating" => 9, "summary" => "With Jinbe having been accepted as a Shichibukai, the Sun Pirates return to Fishman Island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736536.jpg"),
        array("id" => "s2012e17", "season" => 2012, "number" => 17, "name" => "A Sudden Tragedy! A Gunshot Shuts Down The Future!", "airdate" => "6 May 2012", "runtime" => 25, "rating" => 9.3, "summary" => "Vander Decken IX discovers about the Tamatebako and wishes to use it to age Shirahoshi after she grows up a little.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736537.jpg"),
        array("id" => "s2012e18", "season" => 2012, "number" => 18, "name" => "Back To The Present! Hordy Makes A Move!", "airdate" => "13 May 2012", "runtime" => 25, "rating" => 9.1, "summary" => "After Otohime passed away, Hody Jones had found and killed the suspected human assassin and showed him to the people.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736538.jpg"),
        array("id" => "s2012e19", "season" => 2012, "number" => 19, "name" => "The Kingdom In Shock! An Order to Execute Neptune Issued!", "airdate" => "20 May 2012", "runtime" => 25, "rating" => 8.1, "summary" => "Hody makes his announcement to take over the Ryugu Kingdom with the execution of King Neptune as the start of his new rule. Hody also announces that he will kill Straw Hats so that they will serve as example to all humans in the surface.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736539.jpg"),
        array("id" => "s2012e20", "season" => 2012, "number" => 20, "name" => "A Rift Opens Up! Luffy Vs. Jimbei!", "airdate" => "27 May 2012", "runtime" => 25, "rating" => 8.8, "summary" => "Luffy and Jinbe start their duel to see who gets to fight Hody, but their fight was cut short by Sanji's and Robin's interference.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736540.jpg"),
        array("id" => "s2012e21", "season" => 2012, "number" => 21, "name" => "Something Has Happened To Hordy! The True Power Of The Evil Drug!", "airdate" => "3 Jun 2012", "runtime" => 25, "rating" => 7.8, "summary" => "The New Fishman Pirates head to the Gyoncorde Plaza to execute King Neptune but before getting at the plaza, they demonstrate a little taste of their power by terrorizing and destroying everything in their path.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736541.jpg"),
        array("id" => "s2012e22", "season" => 2012, "number" => 22, "name" => "The Battle Is On! At Conchcorde Plaza!", "airdate" => "10 Jun 2012", "runtime" => 25, "rating" => 7.5, "summary" => "Neptune's army put up an attempt to stop Hody Jones and his pirates from reaching Gyoncorde Plaza but seeing the king held hostage prevents them from attacking.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736542.jpg"),
        array("id" => "s2012e23", "season" => 2012, "number" => 23, "name" => "A Surprising Confession! The Truth Behind The Assassination Of Otohime!", "airdate" => "17 Jun 2012", "runtime" => 25, "rating" => 8.3, "summary" => "Jinbe and Shirahoshi are captured by the New Fishman Pirates when they fall into a trap due to a balloon version of King Neptune which easily tricks Shirahoshi and Megalo.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736543.jpg"),
        array("id" => "s2012e24", "season" => 2012, "number" => 24, "name" => "Shirahoshi's Tears! Luffy Finally Shows Up!", "airdate" => "24 Jun 2012", "runtime" => 25, "rating" => 9.4, "summary" => "Shirahoshi reveals that Megalo witnessed Hody shooting Queen Otohime and told her in secret.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736544.jpg"),
        array("id" => "s2012e25", "season" => 2012, "number" => 25, "name" => "A Big Clash! The Straw Hats Vs. A Hundered Thousand Enemies!", "airdate" => "1 Jul 2012", "runtime" => 25, "rating" => 9.5, "summary" => "The citizens celebrate at the arrival of Luffy and his crew. Jinbe comments on how his plan with the Straw Hat Pirates crew worked. Luffy takes down half of Hody's forces with Haki.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736545.jpg"),
        array("id" => "s2012e26", "season" => 2012, "number" => 26, "name" => "Deadly Attacks! Zoro And Sanji Join The Battle!", "airdate" => "8 Jul 2012", "runtime" => 25, "rating" => 9.3, "summary" => "The Straw Hat Pirates begin their attack with Luffy, Zoro and Sanji taking the lead in the fight but mostly it is the latter two of the three who begin showing their new powers and abilities from their two year separation and training.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736546.jpg"),
        array("id" => "s2012e27", "season" => 2012, "number" => 27, "name" => "Unveiled! The Secret Weapons Of The Sunny!", "airdate" => "15 Jul 2012", "runtime" => 25, "rating" => 8.6, "summary" => "The battle rages on between the Straw Hats and the New Fishman Pirates. Sanji and Zoro are competing over who can take down the most fishmen.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736547.jpg"),
        array("id" => "s2012e28", "season" => 2012, "number" => 28, "name" => "Iron Pirate! Here Comes General Franky!", "airdate" => "29 Jul 2012", "runtime" => 25, "rating" => 8.9, "summary" => "The battle between the New Fishman Pirates and the Straw Hats continues, with the Straw Hats gaining the upper hand. Seeing this, Daruma decides to join the fight, targeting the Brachio Tank V and collapsing the ground underneath it.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736548.jpg"),
        array("id" => "s2012e29", "season" => 2012, "number" => 29, "name" => "The Noah Closing In! The Fishman Island Facing Destruction!", "airdate" => "5 Aug 2012", "runtime" => 25, "rating" => 8, "summary" => "Luffy and Hody continue their fight with Luffy getting the upper hand with Haki and Hody's attacks being ineffective against Luffy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736549.jpg"),
        array("id" => "s2012e30", "season" => 2012, "number" => 30, "name" => "Hurry Up Luffy! Shirahoshi's Life In Jeopardy!", "airdate" => "12 Aug 2012", "runtime" => 25, "rating" => 7.9, "summary" => "Shirahoshi begins swimming out to sea in an attempt to lure the ark Noah away and save Fishman Island, while Luffy gets Sanji's help to allow him to reach the ship's chains and stop Hody.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736550.jpg"),
        array("id" => "s2012e31", "season" => 2012, "number" => 31, "name" => "The Fierce Fight Begins! Luffy Vs. Hordy!", "airdate" => "19 Aug 2012", "runtime" => 25, "rating" => 7.9, "summary" => "Hody takes his trident out of Vander Decken's body and, after a short fight, Decken is defeated. Then Hody goes after Shirahoshi, slicing through Ryuboshi and Manboshi, reaches her with his incomparable underwater speed, and grabs her hair.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736551.jpg"),
        array("id" => "s2012e32", "season" => 2012, "number" => 32, "name" => "A Massive Confused Fight! The Straw Hats Vs. The New Fishmen Pirates!", "airdate" => "26 Aug 2012", "runtime" => 25, "rating" => 8.3, "summary" => "Luffy along with the three princes try to protect Shirahoshi against Hody Jones.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736552.jpg"),
        array("id" => "s2012e33", "season" => 2012, "number" => 33, "name" => "Luffy Loses The Fight! Hordy's Long-Awaited Revenge!", "airdate" => "2 Sep 2012", "runtime" => 25, "rating" => 7.9, "summary" => "As the Noah falls onto the Fishman Island, Shirahoshi desperately tries to tell Decken to wake up only for Hody to attack her but Manboshi takes the blunt of the attack.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736553.jpg"),
        array("id" => "s2012e34", "season" => 2012, "number" => 34, "name" => "A Shocking Fact! The True Identity Of Hordy!", "airdate" => "9 Sep 2012", "runtime" => 25, "rating" => 8.3, "summary" => "The story goes back before the Noah started falling back to the island. Jinbe and Sanji continue to fight Wadatsumi and Wadatsumi becomes angry and inflates himself, crushing some of his allies unknowingly.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736554.jpg"),
        array("id" => "s2012e35", "season" => 2012, "number" => 35, "name" => "Back To Zero! Ernest Wishes For Luffy!", "airdate" => "16 Sep 2012", "runtime" => 25, "rating" => 8.5, "summary" => "As Fukaboshi begins to state who Hody really is, Hody's past is revealed as he recalls his hatred towards humans. The New Fish-Man Pirates officers were taught as kids that the humans are an inferior species and that they should be punished by heaven.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736555.jpg"),
        array("id" => "s2012e36", "season" => 2012, "number" => 36, "name" => "Luffy's All Out Attack! Red Hawk Blasts!", "airdate" => "23 Sep 2012", "runtime" => 25, "rating" => 8.5, "summary" => "Brook continues to fight Zeo and reveals his new control over his Yomi Yomi no Mi abilities. Usopp continues to fight Daruma and has set traps for him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736556.jpg"),
        array("id" => "s2012e37", "season" => 2012, "number" => 37, "name" => "Coming To An End! The Final Decisive Battle Against Hordy!", "airdate" => "30 Sep 2012", "runtime" => 25, "rating" => 9.3, "summary" => "Hody recovers thanks to the Energy Steroids and manages to overwhelm Luffy and bite him again in the same spot.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736557.jpg"),
        array("id" => "s2012e38", "season" => 2012, "number" => 38, "name" => "Stop Noah! Desperate Elephant Gatling!", "airdate" => "7 Oct 2012", "runtime" => 25, "rating" => 8.9, "summary" => "All of the New Fishman Pirates lie down defeated while the Straw Hat Pirates are relaxing and waiting for Luffy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736558.jpg"),
        array("id" => "s2012e39", "season" => 2012, "number" => 39, "name" => "To The Future! The Path To The Sun!", "airdate" => "14 Oct 2012", "runtime" => 25, "rating" => 9.4, "summary" => "With the Sea Kings having stopped and saved the great ship Noah, Shirahoshi learns a startling secret from the Sea Kings.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736559.jpg"),
        array("id" => "s2012e40", "season" => 2012, "number" => 40, "name" => "The Secret Revealed! The Truth About The Ancient Weapon!", "airdate" => "21 Oct 2012", "runtime" => 25, "rating" => 8.6, "summary" => "As the whole Fishman Island celebrates the capture and defeat of Hody and the New Fishman Pirates by the Straw Hats, who make their own plans to leave Fishman Island soon.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736560.jpg"),
        array("id" => "s2012e41", "season" => 2012, "number" => 41, "name" => "The Straw Hat's Stunned! The New Fleet Admiral Of The Navy!", "airdate" => "28 Oct 2012", "runtime" => 25, "rating" => 8.9, "summary" => "King Neptune talks about the Ancient Weapons with Shirahoshi and Nico Robin while Caribou listens and makes his way to Shirahoshi's room.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736561.jpg"),
        array("id" => "s2012e42", "season" => 2012, "number" => 42, "name" => "She Loves Sweets! Big Mom Of The Four Emporers!", "airdate" => "4 Nov 2012", "runtime" => 25, "rating" => 9.3, "summary" => "The rest of the Straw Hats are waiting for Luffy, Zoro, and Sanji to return the treasure from Caribou. They find Caribou easily with all the treasure.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736562.jpg"),
        array("id" => "s2012e43", "season" => 2012, "number" => 43, "name" => "Many Problems Lie Ahead! A Trap Awaiting In The New World!", "airdate" => "11 Nov 2012", "runtime" => 25, "rating" => 8.8, "summary" => "The Minister of the Right was thanking the Straw Hats for saving Fishman Island, when suddenly he got a report that the Tamate Box is gone and is in the hands of Baron Tamago and Pekoms.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736563.jpg"),
        array("id" => "s2012e44", "season" => 2012, "number" => 44, "name" => "Finally Time To Go! Goodbye Fishman Island!", "airdate" => "20 Nov 2012", "runtime" => 25, "rating" => 9.1, "summary" => "The mermaids and Keimi from the Mermaid Cafe ask Madam Shyarly if they can say good bye to the Straw Hats. Madam Shyarly says that her prediction that Luffy will destroy Fishman Island was wrong since they defeated Hody and his Pirates.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736564.jpg"),
        array("id" => "s2012e45", "season" => 2012, "number" => 45, "name" => "To the New World! Heading For The Ultimate Sea!", "airdate" => "25 Nov 2012", "runtime" => 25, "rating" => 9.4, "summary" => "The Straw Hats are Heading into the New World.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/294/736565.jpg"),
        array("id" => "s2012e46", "season" => 2012, "number" => 46, "name" => "Z's Ambition Arc - The Little Giant Lily!", "airdate" => "2 Dec 2012", "runtime" => 25, "rating" => 6.8, "summary" => "The Straw Hats find themselves in a middle of an infamous sea in the New World known for its mirages and outrageous weather patterns.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739392.jpg"),
        array("id" => "s2012e47", "season" => 2012, "number" => 47, "name" => "Z's Ambition Arc - Introduction of the Mystery of the Strongest Army Corps!", "airdate" => "9 Dec 2012", "runtime" => 25, "rating" => 7, "summary" => "Nami creates a plan for the Straw Hats to rescue Lily's father, Panz Fry. Chopper, Robin, Brook, and Luffy are the diversion group while Usopp, Sanji, Zoro, and Lily are in the submarine.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739393.jpg"),
        array("id" => "s2012e48", "season" => 2012, "number" => 48, "name" => "Z's Ambition Arc - A Desperate Big Escape Strategy!", "airdate" => "16 Dec 2012", "runtime" => 25, "rating" => 7, "summary" => "Luffy and Zoro face off against Shuzo and Momonga. The Straw Hats, Lily, and her father manage to escape with a Coup de Burst and the anchor connected to the Thousand Sunny.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739394.jpg"),
        array("id" => "s2012e49", "season" => 2012, "number" => 49, "name" => "Z's Ambition Arc - Luffy vs. Shuzo!", "airdate" => "23 Dec 2012", "runtime" => 25, "rating" => 6.8, "summary" => "Shuzo orders his men to be launched at the island like torpedoes and sacrifice themselves for him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739395.jpg"),
    )),
    array("number" => 2013, "name" => "#579 - #626", "rating" => 8.6, "episodes" => array(
        array("id" => "s2013e1", "season" => 2013, "number" => 1, "name" => "Arriving! A Burning Island - Punk Hazard!", "airdate" => "6 Jan 2013", "runtime" => 25, "rating" => 8.3, "summary" => "The Straw Hats have arrived at a volcanic island that does not show on the New World Log Pose. Luffy in his enthusiasm votes to go to the island, though most of the crew were reluctant to go because of the sea of fire blocking their way.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739396.jpg"),
        array("id" => "s2013e2", "season" => 2013, "number" => 2, "name" => "A Battle In The Heat! Luffy Vs. The Giant Dragon!", "airdate" => "13 Jan 2013", "runtime" => 25, "rating" => 7.9, "summary" => "Luffy and Zoro start fighting the dragon, which is shown to be able to speak and breathe fire.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739397.jpg"),
        array("id" => "s2013e3", "season" => 2013, "number" => 3, "name" => "The Straw Hats Stunned! Enter: A Samaura's Horrifying Severed Head!", "airdate" => "20 Jan 2013", "runtime" => 25, "rating" => 8.1, "summary" => "Luffy, Zoro, Usopp, and Robin are standing near the dead dragon that Zoro killed and Luffy is trying to pull out the man who is stuck in the dragon's body.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739398.jpg"),
        array("id" => "s2013e4", "season" => 2013, "number" => 4, "name" => "Startling! The Secret of the Island is Finally Revealed!", "airdate" => "27 Jan 2013", "runtime" => 25, "rating" => 8.3, "summary" => "Franky, Sanji, Nami and Chopper are surprised that the samurai is still alive after being cut.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739399.jpg"),
        array("id" => "s2013e5", "season" => 2013, "number" => 5, "name" => "Save the Children! The Straw Hats Start To Fight!", "airdate" => "3 Feb 2013", "runtime" => 25, "rating" => 8, "summary" => "Nami's group escaped the prison cell and end up in the Biscuits Room, where they find giant children.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739400.jpg"),
        array("id" => "s2013e6", "season" => 2013, "number" => 6, "name" => "A Swordplay Showdown! Brook Vs. The Mysterious Torso Samurai!", "airdate" => "10 Feb 2013", "runtime" => 25, "rating" => 9, "summary" => "At the lake, Luffy's group have been attacked by Brownbeard and his centaur unit who's job was to intercept and eliminate any obvious intruders.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739401.jpg"),
        array("id" => "s2013e7", "season" => 2013, "number" => 7, "name" => "The Warlord! Trafalgar Law!", "airdate" => "17 Feb 2013", "runtime" => 25, "rating" => 8.7, "summary" => "Chopper and Nami, leading the children stumble upon a room with people frozen in it. Franky, Sanji and the samurai start to make their way towards Nami and Chopper. Luffy, Zoro, Usopp and Robin get attacked by the centaurs.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739402.jpg"),
        array("id" => "s2013e8", "season" => 2013, "number" => 8, "name" => "In A Real Pinch! Luffy Sinks Into The Ice-Cold Lake!", "airdate" => "3 Mar 2013", "runtime" => 25, "rating" => 9.6, "summary" => "Luffy, Zoro, Usopp and Robin try to get to the ice side of Punk Hazard but their ship gets capsized by Brownbeard. As Brownbeard's troop prepares attack them again, Zoro gets ready to destroy their bullets but gets dragged down by sharks.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739403.jpg"),
        array("id" => "s2013e9", "season" => 2013, "number" => 9, "name" => "A Collision! Law vs. Vice Admiral Smoker!", "airdate" => "17 Mar 2013", "runtime" => 25, "rating" => 9.4, "summary" => "Law was going to to cut up Tashigi into little pieces but Smoker saved her and started fighting against Law. Luffy, Zoro, Robin and Usopp are riding on top of Brownbeard after defeating him and his centaurs.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739404.jpg"),
        array("id" => "s2013e10", "season" => 2013, "number" => 10, "name" => "Meeting Again After Two Years! Luffy and Law!", "airdate" => "24 Mar 2013", "runtime" => 25, "rating" => 9, "summary" => "Tashigi tries to see what happened in the fight. Luffy's group sees the flying warship. Luffy sees Law and thanks him for saving him two years ago. Law says that they aren't friends and Luffy agrees since they were both after One Piece.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739405.jpg"),
        array("id" => "s2013e11", "season" => 2013, "number" => 11, "name" => "The Worst In The World! A Scientist Of Terror - Caesar!", "airdate" => "31 Mar 2013", "runtime" => 25, "rating" => 8.4, "summary" => "The G-5 Marines discussed if Caesar Clown was probably behind the unusual events at the island and that the child abduction cases in that area may have been real.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739406.jpg"),
        array("id" => "s2013e12", "season" => 2013, "number" => 12, "name" => "History's Strongest Collaboration! Vs. Glutton of the Sea!", "airdate" => "7 Apr 2013", "runtime" => 25, "rating" => 7.3, "summary" => "Featured characters of One Piece, Toriko, and Dragon Ball Z enter the IGO tournament in order to gain the Carat meat, which is said to be the most tasteful in the world. However, it leads in a tie between Goku, Toriko, and Luffy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739407.jpg"),
        array("id" => "s2013e13", "season" => 2013, "number" => 13, "name" => "Chopper's Fury! The Master's Inhumane Experiment!", "airdate" => "14 Apr 2013", "runtime" => 25, "rating" => 8, "summary" => "The children and the Straw Hat Pirates are in a cave with Brownbeard tied up talking about the Master. Zoro, Sanji and Brook go to look for Kin'emon, who had gone to look for his torso.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739408.jpg"),
        array("id" => "s2013e14", "season" => 2013, "number" => 14, "name" => "To Annihlate The Straw Hats! Legendary Assassins Descend!", "airdate" => "21 Apr 2013", "runtime" => 25, "rating" => 8, "summary" => "Yeti Cool Brothers make their way to the destroyed lab where the Straw Hats and the children are. Monet tells Caesar Clown about Law having some relation to Luffy, which makes Caesar mistrust Law until Law reassures him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739409.jpg"),
        array("id" => "s2013e15", "season" => 2013, "number" => 15, "name" => "Save Nami! Luffy's Fight On The Snow-Capped Mountains!", "airdate" => "28 Apr 2013", "runtime" => 25, "rating" => 8.6, "summary" => "Chopper tells the others that Nami in Franky's body was kidnapped by the Yeti Cool Brothers. Franky in Chopper's body takes a Rumble Ball. Luffy and Franky go after the Yeti Cool Brothers to save Nami and defeat them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739410.jpg"),
        array("id" => "s2013e16", "season" => 2013, "number" => 16, "name" => "Formation! The Pirate Alliance Luffy-Law!", "airdate" => "5 May 2013", "runtime" => 25, "rating" => 8, "summary" => "Luffy and Law agree on an alliance; the rest of the Straw Hat Pirates disapprove while Nico Robin approves, even if she warns Luffy about a possible betrayal in a pirate alliance.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739411.jpg"),
        array("id" => "s2013e17", "season" => 2013, "number" => 17, "name" => "Capture M! The Pirate Alliances's Operation Launches!", "airdate" => "12 May 2013", "runtime" => 25, "rating" => 8, "summary" => "Zoro, Sanji and Brook are trying to find the samurai and remember what happened to them. They had been knocked out by the Yeti Cool Brothers, who used a gas that makes people drunk.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739414.jpg"),
        array("id" => "s2013e18", "season" => 2013, "number" => 18, "name" => "On The Verge Of Annihilation! A Deadly Monster Comes Flying In!", "airdate" => "19 May 2013", "runtime" => 25, "rating" => 8, "summary" => "Luffy declares that he will capture Caesar. Law will distract Monet while Chopper finds an antidote for drug.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739415.jpg"),
        array("id" => "s2013e19", "season" => 2013, "number" => 19, "name" => "An Intense Battle! Caesar Exercises His True Power!", "airdate" => "26 May 2013", "runtime" => 25, "rating" => 8.6, "summary" => "Sanji, Kin'emon, Brook and Zoro see Smiley. Brook talks about a story of a creature called Slime which melts the clothes of women, making everyone act perverted except for Zoro, who points out that the slime is killing the fish in the lake.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739416.jpg"),
        array("id" => "s2013e20", "season" => 2013, "number" => 20, "name" => "A Samurai Who Can Cut Fire! Foxfire Kin'Emon!", "airdate" => "2 Jun 2013", "runtime" => 25, "rating" => 8.4, "summary" => "Law's heart is crushed by the mysterious man named Vergo who was sent along with Monet to watch over Caesar.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739417.jpg"),
        array("id" => "s2013e21", "season" => 2013, "number" => 21, "name" => "Shock! Identity of Vergo, the Mysterious Man", "airdate" => "9 Jun 2013", "runtime" => 25, "rating" => 8.8, "summary" => "Law gets beaten up by Vergo. Yarisugi tells the parents of the missing children that they are dead. Caesar takes the children from Usopp and Nami.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739418.jpg"),
        array("id" => "s2013e22", "season" => 2013, "number" => 22, "name" => "Save The Children! The Master's Evil Hands Close In!", "airdate" => "16 Jun 2013", "runtime" => 25, "rating" => 8, "summary" => "As Luffy and Law remain captives in Caesar's lab along with the others who were captured, Caesar Clown goes to retrieve the children from the remaining Straw Hat Pirates.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739419.jpg"),
        array("id" => "s2013e23", "season" => 2013, "number" => 23, "name" => "Shaking Up The New World! Caesar's Horrendous Experiment!", "airdate" => "23 Jun 2013", "runtime" => 25, "rating" => 7.9, "summary" => "At the lab, the G-5 Marine soldiers are banging on the door, demanding entry. Meanwhile, the children were returned to the Lab where Caesar ordered his subordinates to make sure they don't escape again. However, Mocha begins to regain her senses, seeing Caesa…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739420.jpg"),
        array("id" => "s2013e24", "season" => 2013, "number" => 24, "name" => "The Deadliest Weapon of Mass Destruction in History! Land Of The Dead!", "airdate" => "30 Jun 2013", "runtime" => 25, "rating" => 8.4, "summary" => "After Smiley swallows the over-sized candy, the candy coat dissolves revealing a special drug designed to convert the entire content of Smiley's body into a \"perfect\" weapon of destruction, Shinokuni.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739421.jpg"),
        array("id" => "s2013e25", "season" => 2013, "number" => 25, "name" => "The Counterattack Begins! Luffy and Law's Great Escape", "airdate" => "7 Jul 2013", "runtime" => 25, "rating" => 9, "summary" => "As the Underworld Brokers watched the video feed of the captive Straw Hats and Marines, Eustass Kid and Killer decided to ignore it for more important matters, such as forming an alliance between the Kid Pirates, On Air Pirates and the Hawkins Pirates.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739422.jpg"),
        array("id" => "s2013e26", "season" => 2013, "number" => 26, "name" => "Get To Building R! The Pirate Alliance's Great Advance!", "airdate" => "14 Jul 2013", "runtime" => 25, "rating" => 8, "summary" => "Though the Straw Hats and Brownbeard managed to escape into the lab, they left behind a gaping hole. But they soon realise that Shinokuni can now enter the lab.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739423.jpg"),
        array("id" => "s2013e27", "season" => 2013, "number" => 27, "name" => "Tashigi's Tears! G5's Desperate Breakthrough Plan!", "airdate" => "21 Jul 2013", "runtime" => 25, "rating" => 8, "summary" => "Caesar Clown, incensed with the humiliation that his prisoners escaped and are inside his lab, orders the passage between building A and B to be closed and Shinokuni to be let in to kill the intruders. Vergo, however decided to take care of them himself.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739424.jpg"),
        array("id" => "s2013e28", "season" => 2013, "number" => 28, "name" => "The Treacherous Vice Admiral! Demon Bamboo Vergo!", "airdate" => "28 Jul 2013", "runtime" => 25, "rating" => 8.4, "summary" => "Luffy races toward Caesar in the hopes of delivering a beating, Sanji saves a damsel in distress, and Chopper tries to prevent the children from eating the drugged candy!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739425.jpg"),
        array("id" => "s2013e29", "season" => 2013, "number" => 29, "name" => "A Fierce Battle Gets Heated! Luffy vs. Caesar!", "airdate" => "11 Aug 2013", "runtime" => 25, "rating" => 8.7, "summary" => "Sanji and Vergo slug it out in a cloud of toxic gas, Law finds the room that could ruin the New World, and Luffy hopes to bring Caesar`s reign of terror to a brutal end!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739426.jpg"),
        array("id" => "s2013e30", "season" => 2013, "number" => 30, "name" => "The Mastermind in the Shadows! Doflamingo Moves!", "airdate" => "18 Aug 2013", "runtime" => 25, "rating" => 9.2, "summary" => "Doflamingo orders Vergo to stop Law in his tracks, Luffy battles a deadly snowbird, and the rest of the Straw Hats attempt to survive the fiery breath of an angry dragon!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739427.jpg"),
        array("id" => "s2013e31", "season" => 2013, "number" => 31, "name" => "Luffy Dies from Exposure?! The Spine-chilling Snow Woman Monet!", "airdate" => "25 Aug 2013", "runtime" => 25, "rating" => 8.7, "summary" => "Luffy goes down fast after Monet puts a chill into him, and Trafalgar Law makes a desperate attempt to reclaim his heart during an electric battle with Vergo!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739428.jpg"),
        array("id" => "s2013e32", "season" => 2013, "number" => 32, "name" => "Fist Fight! Two Vice Admirals Fight", "airdate" => "1 Sep 2013", "runtime" => 25, "rating" => 8.3, "summary" => "Smoker attacks Vergo for assaulting his men, Luffy meets something strange in the trash heap, and a flashback reveals the true depths of Caesar`s madness!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739429.jpg"),
        array("id" => "s2013e33", "season" => 2013, "number" => 33, "name" => "The Small Dragon! Momonosuke Appears", "airdate" => "8 Sep 2013", "runtime" => 25, "rating" => 8.8, "summary" => "Luffy befriends a dragon that used to be a human boy, and Captain Smoker continues his brutal battle with the villainous Vergo!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739430.jpg"),
        array("id" => "s2013e34", "season" => 2013, "number" => 34, "name" => "Deadly Combat in Snowstorm The Straw Hats vs. the Snow Woman", "airdate" => "15 Sep 2013", "runtime" => 25, "rating" => 8.8, "summary" => "Luffy hitches a ride on a dragon, Mocha tries to keep the Master`s candy away from her friends, and Zoro pits his steel against snow in a battle with Monet!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739431.jpg"),
        array("id" => "s2013e35", "season" => 2013, "number" => 35, "name" => "Showing Off His Techniques! Zoro's Formidable One-Sword Style!", "airdate" => "24 Sep 2013", "runtime" => 25, "rating" => 9.2, "summary" => "To survive his battle with Monet, Zoro must overcome his unwillingness to cut a woman. Elsewhere, Luffy puts a hungry dragon on his back and tries to punch his way out of the basement!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739432.jpg"),
        array("id" => "s2013e36", "season" => 2013, "number" => 36, "name" => "I'll Protect My Friends! Mocha's Desperate Escape", "airdate" => "29 Sep 2013", "runtime" => 25, "rating" => 8.3, "summary" => "Chopper, Nami, and Robin watch in horror as Mocha makes a heartbreaking sacrifice in a courageous attempt to save the lives of her friends!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739433.jpg"),
        array("id" => "s2013e37", "season" => 2013, "number" => 37, "name" => "Brownbeard's In Grief! Luffy Lands A Furious Blow!", "airdate" => "6 Oct 2013", "runtime" => 25, "rating" => 9, "summary" => "Brownbeard heroically attempts to expose Caesar as a villain, the horrific truth about Punk Hazard is finally revealed, and Luffy puts the hurt on his gaseous enemy!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739440.jpg"),
        array("id" => "s2013e38", "season" => 2013, "number" => 38, "name" => "A Surprising Outcome! White Hunter vs. Vergo!", "airdate" => "13 Oct 2013", "runtime" => 25, "rating" => 9.4, "summary" => "Luffy makes Caesar pay for his crimes against the children, and Smoker risks his life for a chance to see Vergo fall in battle!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739441.jpg"),
        array("id" => "s2013e39", "season" => 2013, "number" => 39, "name" => "Caesar Defeat! The Powerful Grizzly Magnum!", "airdate" => "20 Oct 2013", "runtime" => 25, "rating" => 8.9, "summary" => "Law reaches the end of his epic battle with Vergo, and Luffy looks to land a devastating final blow on the murderous gasbag Caesar!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739442.jpg"),
        array("id" => "s2013e40", "season" => 2013, "number" => 40, "name" => "Raid! An Assassin From Dressrosa!", "airdate" => "27 Oct 2013", "runtime" => 25, "rating" => 8.6, "summary" => "Word of Luffy and Law`s alliance spreads throughout the world, Chopper and Brook race to stay ahead of the deadly gas, and Joker sends a team to rescue Caesar!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739443.jpg"),
        array("id" => "s2013e41", "season" => 2013, "number" => 41, "name" => "Runninng Wild! Invincible General Franky!", "airdate" => "3 Nov 2013", "runtime" => 25, "rating" => 9.1, "summary" => "Franky battles a lethal beauty, Caesar tries to strike a final blow against Smoker, and Monet detonates an explosive surprise that could spell doom for the Straw Hats!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739444.jpg"),
        array("id" => "s2013e42", "season" => 2013, "number" => 42, "name" => "A Critical Situation! Punk Hazard Explodes!", "airdate" => "10 Nov 2013", "runtime" => 25, "rating" => 8.9, "summary" => "As the Straw Hats and company flee the crumbling laboratory, Caesar`s desperate act of vengeance thwarts Joker`s plan to forever silence his enemies!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739445.jpg"),
        array("id" => "s2013e43", "season" => 2013, "number" => 43, "name" => "Capture Caesar! General Cannon Blast's!", "airdate" => "17 Nov 2013", "runtime" => 25, "rating" => 8.9, "summary" => "Franky continues his battle with Buffalo and Baby 5, Nami uses a mighty gust of wind to save the children from a deadly cloud of gas, and Usopp takes a shot at capturing Caesar!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739446.jpg"),
        array("id" => "s2013e44", "season" => 2013, "number" => 44, "name" => "A Touching Reunion! Momonosuke and Kin'emon!", "airdate" => "24 Nov 2013", "runtime" => 25, "rating" => 9, "summary" => "A dragon regains his boyish form, a noble warrior once feared dead makes a shocking resurrection, and bitter enemies set aside their differences to enjoy a well-deserved feast!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739447.jpg"),
        array("id" => "s2013e45", "season" => 2013, "number" => 45, "name" => "It's Time To Say Goodbye! Leaving Punk Hazard!", "airdate" => "1 Dec 2013", "runtime" => 25, "rating" => 9, "summary" => "The weary marines and the rescued children get teary-eyed as they say goodbye to the Straw Hats. Meanwhile, Law enters into treacherous negotiations with Joker!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739448.jpg"),
        array("id" => "s2013e46", "season" => 2013, "number" => 46, "name" => "The G-5 Wiped Out! Doflamingo's Sudden Attack!", "airdate" => "8 Dec 2013", "runtime" => 25, "rating" => 9.6, "summary" => "The Straw Hats set a course for Dressrosa, Law explains his alliance with Luffy, and Smoker`s refusal to reveal a secret earns him a serious beating from Doflamingo!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739449.jpg"),
        array("id" => "s2013e47", "season" => 2013, "number" => 47, "name" => "Intense! Aokiji Vs. Doflamingo!", "airdate" => "15 Dec 2013", "runtime" => 25, "rating" => 9.6, "summary" => "Smoker`s life is spared by the arrival of an old friend. Law reveals some shocking news about Caesar`s partnership with Doflamingo, and Momonosuke uses his youth to get cozy with Robin and Nami!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739450.jpg"),
        array("id" => "s2013e48", "season" => 2013, "number" => 48, "name" => "Caesar Goes Missing! The Pirate Alliance Makes A Sortie!", "airdate" => "22 Dec 2013", "runtime" => 25, "rating" => 7.2, "summary" => "Smooth seas stretch out before the Straw Hats as they leave Punk Hazard far behind. While they fear Donflamingo`s return and prepare to face him, another powerful foe lies in wait - one whose power could be their downfall!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739451.jpg"),
    )),
    array("number" => 2014, "name" => "#627 - #676", "rating" => 8.7, "episodes" => array(
        array("id" => "s2014e1", "season" => 2014, "number" => 1, "name" => "Luffy Dies At Sea! The Pirate Alliance Comes Apart!", "airdate" => "5 Jan 2014", "runtime" => 25, "rating" => 7.5, "summary" => "Breed uses his evil abilities to turn Chopper into a pet - and force Luffy and Law to fight to the death.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739452.jpg"),
        array("id" => "s2014e2", "season" => 2014, "number" => 2, "name" => "A Major Turnaround! Luffy's Angry Iron Fist Strikes!", "airdate" => "12 Jan 2014", "runtime" => 25, "rating" => 8.3, "summary" => "After Law discovers the secret to Breed`s power, Luffy and his old friend the Kung Fu Dugong give the animal-abusing madman a beasty beat down!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739453.jpg"),
        array("id" => "s2014e3", "season" => 2014, "number" => 3, "name" => "Startling! The Big News Shakes Up The New World!", "airdate" => "19 Jan 2014", "runtime" => 25, "rating" => 9.1, "summary" => "As the world reacts to Doflamingo`s shocking announcement, Law and the Straw Hats plot the next move in their daring alliance, and a face from the past returns!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739454.jpg"),
        array("id" => "s2014e4", "season" => 2014, "number" => 4, "name" => "Explore! A Kingdom Of Love And Passion - Dresrosa!", "airdate" => "26 Jan 2014", "runtime" => 25, "rating" => 8.4, "summary" => "The Straw Hats and their friends set out to explore Dressrosa, a land full of beautiful women, delicious food, and live toys that walk amongst the living.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739455.jpg"),
        array("id" => "s2014e5", "season" => 2014, "number" => 5, "name" => "Full Of Enthusiasm! The Corrida Colosseum!", "airdate" => "2 Feb 2014", "runtime" => 25, "rating" => 8.7, "summary" => "A blind warrior lays a beat down on a gang of masked thugs, Zorro chases the thief who stole his sword, and Luffy finds himself tempted by the promise of a fiery fruit!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739456.jpg"),
        array("id" => "s2014e6", "season" => 2014, "number" => 6, "name" => "A Dangerous Love! The Dancer Girl - Violet!", "airdate" => "9 Feb 2014", "runtime" => 25, "rating" => 8.4, "summary" => "Zoro continues his hunt for the fairy who stole his sword, Sanji is smitten by a beautiful dancer, and Luffy prepares to fight for the Devil Fruit that belonged to his brother!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739457.jpg"),
        array("id" => "s2014e7", "season" => 2014, "number" => 7, "name" => "A Formidable, Unknown Warrior! Here Comes Lucy!", "airdate" => "16 Feb 2014", "runtime" => 25, "rating" => 8.4, "summary" => "Sanji falls further under the spell of his new lady friend, and Luffy makes quite an impression as he gets to know the fighters competing for Ace`s Devil Fruit.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739458.jpg"),
        array("id" => "s2014e8", "season" => 2014, "number" => 8, "name" => "A Pirate Noble! Cavendish!", "airdate" => "23 Feb 2014", "runtime" => 25, "rating" => 8.4, "summary" => "A gorgeous gladiator tells Luffy the story of the world`s greatest warrior, a masked mauler literally destroys the competition, and the Navy makes its presence felt!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/295/739459.jpg"),
        array("id" => "s2014e9", "season" => 2014, "number" => 9, "name" => "The Fatefull Reunion! Bellamy the Hyena!", "airdate" => "2 Mar 2014", "runtime" => 25, "rating" => 8.4, "summary" => "An old nemesis sees through Luffy`s disguise, Zoro finally catches up to the sword-stealing fairy, and Sanji`s skill at sniffing out snipers impresses his new lady friend!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740736.jpg"),
        array("id" => "s2014e10", "season" => 2014, "number" => 10, "name" => "A Super Rookie! Bartolomeo the Cannibal!", "airdate" => "16 Mar 2014", "runtime" => 25, "rating" => 7.9, "summary" => "Bartolomeo and Bellamy take center stage in the latest round of the battle royal, but a slugger with a serious punch threatens to steal their thunder. Meanwhile, Luffy is targeted by an angry behemoth!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740737.jpg"),
        array("id" => "s2014e11", "season" => 2014, "number" => 11, "name" => "Big Names Duke It Out! The Heated Block B Battle!", "airdate" => "23 Mar 2014", "runtime" => 25, "rating" => 8.1, "summary" => "An old enemy of Garp`s reveals Luffy`s true identity, landing the Straw Hat captain in hot water with one of his fellow competitors. Meanwhile, the battle in Block B gets supremely brutal!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740738.jpg"),
        array("id" => "s2014e12", "season" => 2014, "number" => 12, "name" => "A Deadly Blow! The Astonishing King Punch!", "airdate" => "30 Mar 2014", "runtime" => 25, "rating" => 8.4, "summary" => "Franky`s new robot friend promises to reveal the tragic secrets of Dressrosa, and a regal brawler prepares to throw a powerful punch that could destroy the entire colosseum!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740739.jpg"),
        array("id" => "s2014e13", "season" => 2014, "number" => 13, "name" => "The Fighting Fish Strike! Across The Deadly Iron Bridge!", "airdate" => "6 Apr 2014", "runtime" => 25, "rating" => 7.9, "summary" => "While Law, Robin, Usopp, and Caesar attempt to survive a Fighting Fish attack, Sanji learns the heartbreaking truth about the beautiful woman who stole his heart!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740740.jpg"),
        array("id" => "s2014e14", "season" => 2014, "number" => 14, "name" => "Explore! Fairies' Island - Green Bit!", "airdate" => "13 Apr 2014", "runtime" => 25, "rating" => 8.4, "summary" => "Luffy`s turn to fight in the epic colosseum battle draws near, Zoro has an interesting encounter with a surprisingly strong fairy, and the thoughts in Sanji`s head shock his lady captor!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740741.jpg"),
        array("id" => "s2014e15", "season" => 2014, "number" => 15, "name" => "The Unknown World! The Tontatta Kingdom!", "airdate" => "20 Apr 2014", "runtime" => 25, "rating" => 9, "summary" => "Sanji learns some disturbing news that could mean trouble for his friends, Luffy prepares for a fight, and Robin is captured by a village full of little people!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740742.jpg"),
        array("id" => "s2014e16", "season" => 2014, "number" => 16, "name" => "The Stratagem Of The Century! Doflamingo Makes His Move!", "airdate" => "27 Apr 2014", "runtime" => 25, "rating" => 9, "summary" => "Despite Sanji`s attempt to warn him, Law finds his life in danger after being ambushed by Doflamingo. Meanwhile, Luffy is unable to hide his true identity once the fists start flying!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740743.jpg"),
        array("id" => "s2014e17", "season" => 2014, "number" => 17, "name" => "Shaking Heaven And Earth! Admiral Fujitora's Power!", "airdate" => "4 May 2014", "runtime" => 25, "rating" => 9.1, "summary" => "After his plan falls apart, Law must fight for his life against two powerful opponents. Elsewhere, Sanji bids a touching goodbye to his special lady friend, and Luffy tangles with Brutal Bull!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740744.jpg"),
        array("id" => "s2014e18", "season" => 2014, "number" => 18, "name" => "A Blow of Anger! A Giant vs. Lucy!", "airdate" => "11 May 2014", "runtime" => 25, "rating" => 8.4, "summary" => "Nami, Chopper, and Brook are grotesquely transformed by a hideous woman who fancies herself an artist. Back at the colosseum, Luffy gets serious when his new friend falls victim to a giant attack!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/296/740745.jpg"),
