        array("id" => "s2023e4", "season" => 2023, "number" => 4, "name" => "Luffy Soars! Revenge Against the King of the Beasts", "airdate" => "29 Jan 2023", "runtime" => 25, "rating" => 8.8, "summary" => "Luffy flies on Momonosuke in his giant pink dragon form to get to Onigashima with him. Meanwhile, Yamato vows to survive until Luffy returns.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/444/1112029.jpg"),
