        array("id" => "s2023e7", "season" => 2023, "number" => 7, "name" => "The Situation Has Grown Tense! The End of Onigashima!", "airdate" => "19 Feb 2023", "runtime" => 25, "rating" => 8, "summary" => "While Zoro and Sanji are in a battle against King a Queen, Yamato and Momonosuke launch a secret operation.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/448/1121062.jpg"),
