        array("id" => "s2026e4", "season" => 2026, "number" => 4, "name" => "Destroy the Miniature Garden - Escape Block Kingdom!", "airdate" => "26 Apr 2026", "runtime" => 25, "rating" => 9, "summary" => "Pursued by the Sun God, the Straw Hats flee across Block Kingdom at full speed. Amidst the chaos, the Sun God's true objective begins to surface. But as they run, another wall blocks their path. Their breakthrough rests on Luffy's fists.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/622/1555306.jpg"),
