        array("id" => "s2026e13", "season" => 2026, "number" => 13, "name" => "Ancient History - The Harley Passed Down by Elbaph", "airdate" => "28 Jun 2026", "runtime" => 25, "rating" => 9, "summary" => "Leaving behind a brutal parting gift, Shamrock and Gunko of the Knights of God abandon Loki and move on to their next strategy. Meanwhile, Franky is shown old wall paintings, and Robin reads an important religious text passed down since ancient times in Elbap…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/632/1580528.jpg"),
        array("id" => "s2026e14", "season" => 2026, "number" => 14, "name" => "The Legend Lurking in Elbaph - The Identity of the Mountain-Eater", "airdate" => "12 Jul 2026", "runtime" => 25, "rating" => null, "summary" => "While exploring the abandoned castle, Luffy and the others find a strange mark on the floor of the throne room and hear a mysterious voice out of nowhere. At the banquet, Oimo tells Usopp the tale of a legendary man linked to the Pirate King.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/632/1580527.jpg"),
