        array("id" => "s2026e16", "season" => 2026, "number" => 16, "name" => "The Heinous Sinner - Loki of the Underworld Freed?!", "airdate" => "26 Jul 2026", "runtime" => 25, "rating" => null, "summary" => "While observing the Jewel Tree Adam along with Ripley, Franky learns of Elbaph's weak points. Meanwhile, in the Underworld, Luffy and Zoro find a heavily injured Loki. As they argue over whether to unchain him, an unexpected turn of events blindsides them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/634/1585271.jpg"),
        array("id" => "s2026e17", "season" => 2026, "number" => 17, "name" => "What I Fear Most", "airdate" => "2 Aug 2026", "runtime" => 25, "rating" => null, "summary" => "A massive snake suddenly attacks the Walrus School. Saul and the other teachers stand their ground to protect the children, but just then, another mystery strikes, plunging the school into pure panic.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/635/1587795.jpg"),
        array("id" => "s2026e18", "season" => 2026, "number" => 18, "name" => "A Nightmarish Game - The Dark Plot of the Knights of God", "airdate" => "9 Aug 2026", "runtime" => 25, "rating" => null, "summary" => "Saul tries to stop the marching children, but as he reaches out to them, some unknown force gets in his way. Meanwhile, hearing the school's emergency call throws Dorry and the others at the Western Village into disarray, just as a monster appears before them…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/636/1590155.jpg"),
