        array("id" => "s2026e21", "season" => 2026, "number" => 21, "name" => "The Threat of the Arrow-Arrow Fruit - Gunko vs. the Straw Hats", "airdate" => "30 Aug 2026", "runtime" => 25, "rating" => null, "summary" => "Gunko from the Knights of God shows up right in front of Nami and the others and reveals to them that their plan is to take the children to Mary Geoise. Enraged, the Straw Hats launch an attack, only to be completely overwhelmed by Gunko's extraordinary power.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/639/1597833.jpg"),
